</svg>

<div class="app" id="app">

  <!-- ================= RAIL ================= -->
  <nav class="rail" aria-label="主导航">
    <a class="brand" href="#" aria-label="Agent Hub 首页">
      <svg class="brand-mark" viewBox="0 0 24 24" aria-hidden="true">
        <path d="M4.5 6.5h5.2a3.8 3.8 0 0 1 3.8 3.8v3.4a3.8 3.8 0 0 0 3.8 3.8h2.2"/>
        <circle cx="4.5" cy="6.5" r="1.9"/>
        <circle class="hot" cx="19.5" cy="17.5" r="2"/>
      </svg>
    </a>

    <div class="rail-nav">
      <button class="rail-item is-active" aria-current="page" title="对话">
        <svg class="ic" aria-hidden="true"><use href="#i-chat"/></svg>
        <span>对话</span>
      </button>
      <button class="rail-item" title="会话">
        <svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>
        <span>会话</span>
      </button>
      <button class="rail-item" title="智能体">
        <svg class="ic" aria-hidden="true"><use href="#i-bot"/></svg>
        <span>智能体</span>
      </button>
