<script>
(function () {
  'use strict';

  var root = document.documentElement;
  var app = document.getElementById('app');
  var stream = document.getElementById('stream');
  var thread = document.getElementById('thread');
  var input = document.getElementById('composerInput');
  var sendBtn = document.getElementById('sendBtn');
  var toast = document.getElementById('toast');
  var toastText = document.getElementById('toastText');
  var approvalCard = document.getElementById('approvalCard');
  var approvalStatus = document.getElementById('approvalStatus');
  var resolvedText = document.getElementById('resolvedText');
  var traceToggle = document.getElementById('traceToggle');
  var traceClose = document.getElementById('traceClose');
  var approvalPending = true;
  var toastTimer = null;

  /* ---------- theme ---------- */
  try {
    var savedTheme = localStorage.getItem('ah-theme');
    if (savedTheme === 'dark' || savedTheme === 'light') root.dataset.theme = savedTheme;
  } catch (e) { /* file:// storage may be unavailable */ }

  document.getElementById('themeToggle').addEventListener('click', function () {
    var next = root.dataset.theme === 'dark' ? 'light' : 'dark';
    root.dataset.theme = next;
    try { localStorage.setItem('ah-theme', next); } catch (e) {}
    showToast(next === 'dark' ? '已切换到深色主题' : '已切换到浅色主题');
  });

  /* ---------- toast ---------- */
  function showToast(text) {
    toastText.textContent = text;
    toast.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toast.classList.remove('is-visible');
    }, 2400);
  }

  /* ---------- trace panel ---------- */
  var wide = window.matchMedia('(min-width: 1181px)');

  function setTraceExpanded(expanded) {
    traceToggle.setAttribute('aria-expanded', String(expanded));
  }

  traceToggle.addEventListener('click', function () {
    if (wide.matches) {
      var collapsed = app.classList.toggle('trace-collapsed');
      setTraceExpanded(!collapsed);
    } else {
      var open = app.classList.toggle('trace-open');
      setTraceExpanded(open);
    }
  });

  traceClose.addEventListener('click', function () {
    if (wide.matches) {
      app.classList.add('trace-collapsed');
      setTraceExpanded(false);
    } else {
      app.classList.remove('trace-open');
      setTraceExpanded(false);
    }
  });

  wide.addEventListener('change', function () {
    app.classList.remove('trace-open');
    if (wide.matches) {
      app.classList.remove('trace-collapsed');
      setTraceExpanded(true);
    }
  });

  /* ---------- session list ---------- */
  var sessions = Array.prototype.slice.call(document.querySelectorAll('.session'));
  sessions.forEach(function (item) {
    item.addEventListener('click', function () {
      sessions.forEach(function (s) {
        s.classList.remove('is-active');
        s.removeAttribute('aria-current');
      });
      item.classList.add('is-active');
      item.setAttribute('aria-current', 'page');
    });
  });

  document.getElementById('newSession').addEventListener('click', function () {
    showToast('新会话已创建（原型演示）');
  });

  var search = document.getElementById('sessionSearch');
  search.addEventListener('input', function () {
    var q = search.value.trim().toLowerCase();
    var groups = document.querySelectorAll('.session-group');
    sessions.forEach(function (item) {
      var title = item.querySelector('.session-title').textContent.toLowerCase();
      item.hidden = q !== '' && title.indexOf(q) === -1;
    });
    groups.forEach(function (group) {
      var visible = Array.prototype.some.call(group.querySelectorAll('.session'), function (s) {
        return !s.hidden;
      });
      group.hidden = !visible;
    });
  });

  /* ---------- approval ---------- */
  approvalCard.querySelectorAll('[data-decision]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var decision = btn.getAttribute('data-decision');
      approvalPending = false;
      approvalCard.classList.add('is-resolved');
      if (decision === 'approve') {
        approvalStatus.textContent = '已批准';
        approvalStatus.className = 'status-chip is-ok';
        resolvedText.textContent = '已批准，周报已发送到 #support-weekly。';
        showToast('已批准并发送到 #support-weekly');
      } else {
        approvalStatus.textContent = '已拒绝';
        approvalStatus.className = 'status-chip';
        resolvedText.textContent = '已拒绝，main-agent 不会发送这条消息。';
        showToast('已拒绝本次发送');
      }
      updateSendState();
    });
  });

  /* ---------- cancel task ---------- */
  var cancelBtn = document.querySelector('[data-cancel-task]');
  if (cancelBtn) {
    cancelBtn.addEventListener('click', function () {
      cancelBtn.disabled = true;
      cancelBtn.textContent = '正在取消…';
      setTimeout(function () {
        cancelBtn.textContent = '已取消';
        showToast('任务 task_7c1e 已取消');
      }, 700);
    });
  }

  /* ---------- composer ---------- */
  function autoGrow() {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 168) + 'px';
  }

  function updateSendState() {
    var hasText = input.value.trim().length > 0;
    sendBtn.classList.toggle('is-disabled', !hasText || approvalPending);
    sendBtn.disabled = !hasText || approvalPending;
    sendBtn.title = approvalPending ? '请先处理上方的发送审批' : '发送';
  }

  input.addEventListener('input', function () {
    autoGrow();
    updateSendState();
  });

  input.addEventListener('keydown', function (event) {
    if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) {
      event.preventDefault();
      send();
    }
  });

  sendBtn.addEventListener('click', send);

  function nowTime() {
    var d = new Date();
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  function makeEntry(className, who, whoSub, bodyHTML) {
    var li = document.createElement('li');
    li.className = 'entry ' + className;
    li.innerHTML =
      '<span class="node" aria-hidden="true"></span>' +
      '<div class="entry-head">' +
        '<span class="who"></span>' +
        '<span class="who-sub"></span>' +
        '<span class="spacer"></span>' +
        '<time></time>' +
      '</div>' +
      '<div class="entry-body"></div>';
    li.querySelector('.who').textContent = who;
    li.querySelector('.who-sub').textContent = whoSub;
    li.querySelector('time').textContent = nowTime();
    li.querySelector('.entry-body').innerHTML = bodyHTML;
    return li;
  }

  function scrollToBottom() {
    stream.scrollTop = stream.scrollHeight;
  }

  function send() {
    var text = input.value.trim();
    if (!text) return;
    if (approvalPending) {
      showToast('请先处理上方的发送审批');
      return;
    }

    var bubble = document.createElement('p');
    bubble.className = 'prompt-bubble';
    bubble.textContent = text;
    var userEntry = makeEntry('entry-user', '你', '通过 Web 工作台', '');
    userEntry.querySelector('.entry-body').appendChild(bubble);
    thread.appendChild(userEntry);

    input.value = '';
    autoGrow();
    updateSendState();
    scrollToBottom();

    var reply = makeEntry(
      'entry-assistant',
      'main-agent',
      '调度员',
      '<div class="prose"><p class="typing" aria-label="正在生成">· · ·</p></div>'
    );
    thread.appendChild(reply);
    scrollToBottom();

    setTimeout(function () {
      reply.querySelector('.entry-body').innerHTML =
        '<div class="prose"><p>收到，我会把这条补充并入周报，并在下一次发送前再次向你确认。</p></div>';
      scrollToBottom();
    }, 1300);
  }

  updateSendState();
  autoGrow();
})();
</script>
</body>
</html>
