}
.btn-new:hover{border-color:var(--ink-3);background:var(--surface)}
.btn-new .ic{width:14px;height:14px}

.search{
  position:relative;
  display:block;
  margin:0 16px 12px;
}
.search .ic{
  position:absolute;left:10px;top:50%;transform:translateY(-50%);
  width:15px;height:15px;color:var(--ink-3);
}
.search input{
  width:100%;height:34px;
  padding:0 10px 0 32px;
  border:1px solid transparent;
  border-radius:6px;
  background:var(--surface-2);
  color:var(--ink);
  font:inherit;font-size:12.5px;
  outline:none;
  transition:border-color .15s, background .15s;
}
.search input::placeholder{color:var(--ink-3)}
.search input:focus{border-color:var(--line);background:var(--surface)}

.session-scroll{flex:1;overflow-y:auto;padding:0 8px 12px;min-height:0}
.session-group{padding-top:10px}
.group-label{
  padding:0 10px 6px;
  font-size:11px;font-weight:500;
  color:var(--ink-3);
  letter-spacing:.03em;
}
.session{
  display:block;width:100%;text-align:left;
  padding:9px 10px 9px 12px;
  border-radius:6px;
  border-left:2px solid transparent;
  transition:background .12s;
}
.session:hover{background:rgba(20,27,32,.045)}
html[data-theme="dark"] .session:hover{background:rgba(255,255,255,.04)}
.session.is-active{background:var(--surface);border-left-color:var(--ink);box-shadow:var(--shadow-sm)}
.session-title{
  display:block;
  font-size:13px;font-weight:550;letter-spacing:-.005em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.session.is-active .session-title{font-weight:650}
.session-meta{
  display:flex;align-items:center;gap:6px;
  margin-top:4px;
  font-size:11px;color:var(--ink-3);
}
.session-meta .dot{width:5px;height:5px}
.session-meta .sep{opacity:.5}

.dot{
  display:inline-block;flex:none;
  width:6px;height:6px;border-radius:50%;
  background:var(--ink-3);
}
.dot.is-live{background:var(--amber);box-shadow:0 0 0 3px var(--amber-soft);animation:pulse 2.4s ease-in-out infinite}
.dot.is-ok{background:var(--green)}
.dot.is-warn{background:var(--red)}

.sessions-foot{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;gap:8px;
  padding:10px 16px;
  border-top:1px solid var(--line);
  font-size:11px;color:var(--ink-3);
}
.conn{display:flex;align-items:center;gap:7px}
.sessions-foot .mono{font-size:10px;letter-spacing:.02em}

/* ============================================================
   CHAT COLUMN
   ============================================================ */
.chat{
  display:flex;flex-direction:column;
  min-width:0;min-height:0;
  background:var(--paper);
  position:relative;
}
.chat-head{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  min-height:68px;
  padding:0 32px;
  border-bottom:1px solid var(--line);
  background:var(--paper);
}
.chat-heading{min-width:0}
.chat-title{
  font-size:16px;font-weight:650;letter-spacing:-.012em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.chat-sub{
  display:flex;align-items:center;gap:8px;
  margin-top:3px;
  font-size:11.5px;color:var(--ink-3);
  white-space:nowrap;overflow:hidden;
}
.chat-sub .mono{font-size:10.5px;color:var(--ink-3)}
.chat-sub .sep{opacity:.45}
.chat-actions{display:flex;align-items:center;gap:8px;flex:none}

.status-chip{
  display:inline-flex;align-items:center;gap:6px;
  height:26px;padding:0 9px;
  border:1px solid var(--line);
  border-radius:5px;
  background:var(--surface);
  color:var(--ink-2);
  font-size:11.5px;font-weight:500;
  white-space:nowrap;
}
.status-chip .dot{width:5px;height:5px}
.status-chip.is-live{border-color:var(--amber-soft);background:var(--amber-soft);color:var(--amber-text)}
.status-chip.is-warn{border-color:var(--red-soft);background:var(--red-soft);color:var(--red)}
.status-chip.is-ok{border-color:var(--green-soft);background:var(--green-soft);color:var(--green)}

.icon-btn{
  display:grid;place-items:center;
  width:30px;height:30px;
  border:1px solid var(--line);
  border-radius:5px;
  background:var(--surface);
  color:var(--ink-2);
  transition:color .15s,border-color .15s;
}
.icon-btn:hover{color:var(--ink);border-color:var(--ink-3)}
.icon-btn .ic{width:16px;height:16px}

.stream{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden}
.stream-inner{
  max-width:812px;
  margin:0 auto;
  padding:30px 36px 16px;
}

/* ---------- timeline bus ---------- */
.thread{position:relative;padding-bottom:6px}
.thread::before{
  content:"";
  position:absolute;left:21px;top:10px;bottom:14px;
  width:1px;
  background:var(--line);
}
.entry{position:relative;padding-left:52px;margin-bottom:26px}
.entry:last-child{margin-bottom:8px}
.node{
  position:absolute;left:17.5px;top:5px;
  width:8px;height:8px;
  background:var(--paper);
  border:1.5px solid var(--ink-2);
  border-radius:50%;
  z-index:1;
}
.entry-user .node{background:var(--ink);border-color:var(--ink)}
.entry-tool .node{
  border-radius:1.5px;border-color:var(--amber);background:var(--surface);
}
.entry-a2a .node{
  border-radius:1px;border-color:var(--prussian);
  transform:rotate(45deg);background:var(--prussian-soft);
}
.entry-approval .node{border-color:var(--red);background:var(--red-soft)}

.entry-head{
  display:flex;align-items:baseline;gap:9px;
  min-height:18px;
  margin-bottom:7px;
}
.who{font-size:12.5px;font-weight:650;letter-spacing:-.005em}
.who-sub{font-size:11px;color:var(--ink-3)}
.entry-head time{
  font-family:var(--font-mono);
  font-size:10.5px;color:var(--ink-3);
  letter-spacing:.01em;
}
.entry-head .spacer{flex:1}
.copy-btn{
  display:inline-flex;align-items:center;gap:4px;
  font-size:11px;color:var(--ink-3);
  opacity:0;transition:opacity .15s,color .15s;
}
.entry:hover .copy-btn,.copy-btn:focus-visible{opacity:1}
.copy-btn:hover{color:var(--ink)}
.copy-btn .ic{width:13px;height:13px}

/* user message */
.prompt-bubble{
  display:inline-block;
  max-width:100%;
  padding:12px 16px;
  border:1px solid var(--line-2);
  border-radius:7px;
  background:var(--surface-2);
  font-size:14.5px;line-height:1.7;
  color:var(--ink);
}
.attachments{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.attach{
  display:inline-flex;align-items:center;gap:7px;
  height:28px;padding:0 10px;
  border:1px solid var(--line);
  border-radius:5px;
  background:var(--surface);
  font-size:11.5px;color:var(--ink-2);
}
.attach .ic{width:14px;height:14px;color:var(--ink-3)}
.attach .mono{font-size:10.5px;color:var(--ink-3)}

/* assistant prose */
.prose{font-size:14.5px;line-height:1.78;color:var(--ink)}
.prose > * + *{margin-top:13px}
.prose h3{
  font-size:19px;font-weight:650;letter-spacing:-.018em;line-height:1.35;
  margin-top:2px;
}
.prose h4{
  font-size:13.5px;font-weight:650;letter-spacing:.005em;
  color:var(--ink);
  margin-top:22px;
}
.prose strong{font-weight:650}
.prose p{max-width:68ch}
.prose .cite{
  display:inline-grid;place-items:center;
  min-width:14px;height:14px;
  margin-left:2px;padding:0 3px;
  border-radius:3px;
  background:var(--prussian-soft);
  color:var(--prussian);
  font-family:var(--font-mono);
  font-size:9px;font-weight:600;
  vertical-align:2px;
  line-height:1;
}
.prose blockquote{
  margin:18px 0 0;
  padding:2px 0 2px 14px;
  border-left:2px solid var(--line);
  color:var(--ink-2);
  font-size:13px;line-height:1.75;
}
.prose ul{max-width:66ch;padding-left:0}
.prose ul li{
  position:relative;
  padding-left:16px;
  margin-top:7px;
}
.prose ul li::before{
  content:"";
  position:absolute;left:2px;top:.72em;
  width:4px;height:1px;
  background:var(--ink-3);
}
.prose code{
  font-family:var(--font-mono);
  font-size:.9em;
  padding:1px 4px;
  border-radius:3px;
  background:var(--surface-2);
  border:1px solid var(--line-2);
}

/* data table */
.data-table{
  width:100%;
  margin-top:16px;
  border-collapse:collapse;
  font-size:13px;
  font-variant-numeric:tabular-nums;
}
.data-table caption{
  text-align:left;
  font-size:11px;color:var(--ink-3);
  padding-bottom:7px;
}
.data-table th{
  text-align:left;
  padding:7px 8px;
  font-size:11px;font-weight:500;
  color:var(--ink-3);
  letter-spacing:.02em;
  border-bottom:1px solid var(--line);
  white-space:nowrap;
}
.data-table th.num,.data-table td.num{text-align:right}
.data-table td{
  padding:9px 8px;
  border-bottom:1px solid var(--line-2);
  color:var(--ink-2);
}
.data-table td:first-child{color:var(--ink);font-weight:500}
.data-table tr:last-child td{border-bottom:1px solid var(--line)}
.data-table .delta-up{color:var(--red)}
.data-table .delta-down{color:var(--green)}

/* ---------- tool card ---------- */
.tool-card{
  border:1px solid var(--line-2);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.tool-card summary{
  display:flex;align-items:center;gap:10px;
  padding:9px 12px;
  cursor:pointer;
  list-style:none;
  user-select:none;
}
.tool-card summary::-webkit-details-marker{display:none}
.tool-card summary:hover{background:var(--surface-2)}
.tool-name{
  font-family:var(--font-mono);
  font-size:12px;font-weight:500;
  color:var(--ink);
  white-space:nowrap;
}
.tool-args{
  font-family:var(--font-mono);
  font-size:11.5px;color:var(--ink-3);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  flex:1;min-width:0;
}
.tool-result{
  display:inline-flex;align-items:center;gap:4px;
  font-size:11px;font-weight:500;color:var(--green);
  white-space:nowrap;
}
.tool-result .ic{width:12px;height:12px;stroke-width:2}
.tool-time{
  font-family:var(--font-mono);
  font-size:10.5px;color:var(--ink-3);
  white-space:nowrap;
}
.chev{width:14px;height:14px;color:var(--ink-3);transition:transform .18s}
.tool-card[open] .chev{transform:rotate(180deg)}
.tool-body{
  border-top:1px solid var(--line-2);
  padding:9px 12px 11px;
  background:var(--surface-2);
}
.hit{
  display:flex;align-items:baseline;gap:8px;
  padding:5px 0;
  font-size:12px;
  border-bottom:1px dashed var(--line-2);
}
.hit:last-child{border-bottom:0}
.hit-title{color:var(--ink);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hit-score{font-family:var(--font-mono);font-size:10.5px;color:var(--prussian)}
.hit-date{font-family:var(--font-mono);font-size:10px;color:var(--ink-3)}
.tool-note{
  margin-top:7px;
  font-family:var(--font-mono);
  font-size:10px;color:var(--ink-3);
}

/* ---------- A2A task card ---------- */
.a2a-card{
  border:1px solid var(--line);
  border-left:3px solid var(--amber);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.a2a-top{display:flex;align-items:flex-start;gap:11px;padding:13px 15px 11px}
.agent-badge{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;
  border:1px solid var(--line);
  border-radius:5px;
  background:var(--surface-2);
  font-family:var(--font-mono);
  font-size:11px;font-weight:700;
  color:var(--prussian);
}
.a2a-ident{flex:1;min-width:0}
.a2a-name{
  display:flex;align-items:center;gap:8px;
  font-size:13px;font-weight:650;letter-spacing:-.005em;
}
.tag{
  display:inline-flex;align-items:center;
  height:17px;padding:0 5px;
  border:1px solid var(--line);
  border-radius:3px;
  font-family:var(--font-mono);
  font-size:9.5px;font-weight:400;
  color:var(--ink-3);
  white-space:nowrap;
}
.a2a-task{margin-top:3px;font-size:12px;color:var(--ink-2)}
.a2a-status{
  display:inline-flex;align-items:center;gap:6px;
  font-size:11.5px;font-weight:500;color:var(--amber-text);
  white-space:nowrap;
}
.progress{
  height:3px;
  margin:0 15px;
  border-radius:99px;
  background:var(--line-2);
  overflow:hidden;
}
.progress span{
  display:block;height:100%;
  border-radius:99px;
  background:var(--amber);
  transition:width .4s ease;
}
.steps{
  display:flex;flex-wrap:wrap;align-items:center;
  gap:0 6px;
  padding:10px 15px 9px;
  font-size:11px;color:var(--ink-3);
}
.steps .step{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}
.steps .step .ic{width:11px;height:11px;stroke-width:2.2}
.steps .step.is-done{color:var(--ink-2)}
.steps .step.is-now{color:var(--amber-text);font-weight:500}
.steps .step.is-now .dot{width:4px;height:4px;background:var(--amber)}
.steps .arrow{width:11px;height:11px;color:var(--line);stroke-width:2}
.a2a-foot{
  display:flex;align-items:center;gap:10px;
  padding:8px 15px;
  border-top:1px solid var(--line-2);
  background:var(--surface-2);
  font-family:var(--font-mono);
  font-size:10px;color:var(--ink-3);
}
.a2a-foot .spacer{flex:1}
.btn-ghost{
  display:inline-flex;align-items:center;gap:5px;
  height:24px;padding:0 8px;
  border:1px solid var(--line);
  border-radius:4px;
  background:var(--surface);
  font-family:var(--font-sans);
  font-size:11px;color:var(--ink-2);
  transition:color .15s,border-color .15s;
}
.btn-ghost:hover{color:var(--ink);border-color:var(--ink-3)}
.btn-ghost .ic{width:12px;height:12px}

/* ---------- approval card ---------- */
.approval-card{
  border:1px solid var(--line);
  border-left:3px solid var(--red);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.approval-head{
  display:flex;align-items:center;gap:8px;
  padding:13px 15px 0;
}
.approval-head .ic{width:15px;height:15px;color:var(--red)}
.approval-title{font-size:13px;font-weight:650;letter-spacing:-.005em}
.approval-head .status-chip{margin-left:auto;height:22px;font-size:10.5px;padding:0 7px}
.approval-body{padding:8px 15px 14px}
.approval-action{font-size:13.5px;line-height:1.6;color:var(--ink)}
.approval-action b{font-weight:650}
.risk-list{
  display:grid;grid-template-columns:auto 1fr;
  gap:3px 12px;
  margin-top:11px;
  font-size:11.5px;
}
.risk-list dt{color:var(--ink-3)}
.risk-list dd{color:var(--ink-2)}
.approval-actions{
  display:flex;align-items:center;gap:8px;
  padding:10px 15px;
  border-top:1px solid var(--line-2);
  background:var(--surface-2);
}
.approval-actions .spacer{flex:1}
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  height:31px;padding:0 13px;
  border-radius:5px;
  font-size:12.5px;font-weight:550;
  transition:background .15s,color .15s,border-color .15s;
  white-space:nowrap;
}
.btn .ic{width:14px;height:14px}
.btn-primary{background:var(--btn-bg);color:var(--btn-fg);border:1px solid var(--btn-bg)}
.btn-primary:hover{background:var(--prussian);border-color:var(--prussian);color:#FBFAF5}
html[data-theme="dark"] .btn-primary:hover{background:var(--amber);border-color:var(--amber);color:#141B20}
.btn-outline{background:transparent;color:var(--ink-2);border:1px solid var(--line)}
.btn-outline:hover{color:var(--ink);border-color:var(--ink-3)}
.btn[disabled]{opacity:.42;cursor:not-allowed}
.approval-card.is-resolved .approval-actions{display:none}
.approval-card.is-resolved{border-left-color:var(--green)}
.approval-card.is-resolved .approval-head .ic{color:var(--green)}
.resolved-note{
  display:none;
  align-items:center;gap:7px;
  padding:10px 15px;
  border-top:1px solid var(--line-2);
  background:var(--green-soft);
  font-size:11.5px;color:var(--green);
}
.approval-card.is-resolved .resolved-note{display:flex}
.resolved-note .ic{width:14px;height:14px}

/* thread footer */
.thread-foot{
  display:flex;align-items:center;gap:8px;
  margin-left:52px;
  padding-top:2px;
  font-size:11px;color:var(--ink-3);
}
.thread-foot .mono{font-size:10px}
.thread-foot::before{
  content:"";
  width:18px;height:1px;background:var(--line);
}

/* ---------- composer ---------- */
.composer-wrap{
  flex:none;
  padding:10px 32px 14px;
  background:linear-gradient(var(--paper) 0%, var(--paper) 100%);
}
.composer-inner{max-width:812px;margin:0 auto}
.composer{
  border:1px solid var(--line);
  border-radius:9px;
  background:var(--surface);
  box-shadow:var(--shadow-md);
  transition:border-color .15s;
}
.composer:focus-within{border-color:var(--ink-3)}
.composer textarea{
  display:block;width:100%;
  min-height:48px;max-height:168px;
  padding:13px 15px 4px;
  border:0;outline:none;resize:none;
  background:transparent;
  color:var(--ink);
  font:inherit;font-size:14px;line-height:1.65;
}
.composer textarea::placeholder{color:var(--ink-3)}
.composer-bar{
  display:flex;align-items:center;gap:6px;
  padding:5px 8px 7px 9px;
}
.composer-tool{
  display:inline-flex;align-items:center;gap:5px;
  height:27px;padding:0 8px;
  border-radius:4px;
  color:var(--ink-3);
  font-size:11.5px;
  transition:background .15s,color .15s;
}
.composer-tool:hover{background:var(--surface-2);color:var(--ink)}
.composer-tool .ic{width:14px;height:14px}
.model-chip{
  display:inline-flex;align-items:center;gap:5px;
  height:23px;padding:0 7px;
  margin-left:2px;
  border:1px solid var(--line-2);
  border-radius:4px;
  font-family:var(--font-mono);
  font-size:10px;color:var(--ink-3);
  white-space:nowrap;
}
.model-chip .dot{width:4px;height:4px;background:var(--green)}
.composer-bar .spacer{flex:1}
.send{
  display:grid;place-items:center;
  width:32px;height:32px;
  border-radius:6px;
  background:var(--btn-bg);
  color:var(--btn-fg);
  transition:opacity .15s,background .15s;
}
.send:hover{background:var(--prussian)}
html[data-theme="dark"] .send:hover{background:var(--amber);color:#141B20}
.send .ic{width:16px;height:16px;stroke-width:2}
.send.is-disabled{opacity:.35;cursor:not-allowed}
.composer-hint{
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
  margin-top:7px;
  padding:0 3px;
  font-size:10.5px;color:var(--ink-3);
}
.composer-hint .spacer{flex:1}
kbd{
  display:inline-block;
  padding:1px 4px;
  border:1px solid var(--line);
  border-bottom-width:2px;
  border-radius:3px;
  background:var(--surface);
  font-family:var(--font-mono);
  font-size:9.5px;
  color:var(--ink-2);
  line-height:1.4;
}

/* ============================================================
   TRACE PANEL
   ============================================================ */
.trace{
  display:flex;flex-direction:column;min-height:0;
  background:var(--surface);
  border-left:1px solid var(--line);
  transition:opacity .18s;
}
.trace-head{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;
  min-height:68px;
  padding:0 18px;
  border-bottom:1px solid var(--line);
}
.trace-title{display:flex;align-items:baseline;gap:7px}
.trace-title h2{font-size:13px;font-weight:650;letter-spacing:-.005em}
.trace-title span{font-size:10.5px;color:var(--ink-3)}
.trace-scroll{flex:1;overflow-y:auto;min-height:0;padding:16px 18px 24px}

.run-line{display:flex;align-items:center;gap:8px;font-size:12px}
.run-line strong{font-weight:600;color:var(--ink)}
.run-line .mono{margin-left:auto;font-size:10px;color:var(--ink-3)}
.run-line .dot{width:6px;height:6px}

.metrics{
  display:grid;grid-template-columns:1fr 1fr;
  gap:0 16px;
  margin-top:12px;
  border-top:1px solid var(--line-2);
}
.metric{padding:10px 0 9px;border-bottom:1px solid var(--line-2)}
.metric dt{font-size:10.5px;color:var(--ink-3)}
.metric dd{margin-top:2px;font-family:var(--font-mono);font-size:13px;font-weight:500;color:var(--ink)}
.metric dd small{font-family:var(--font-sans);font-size:10px;font-weight:400;color:var(--ink-3);margin-left:2px}

.trace-section{margin-top:22px}
.trace-section-head{
  display:flex;align-items:center;gap:6px;
  margin-bottom:10px;
}
.trace-section-head h3{font-size:11.5px;font-weight:600;color:var(--ink-2);letter-spacing:.01em}
.trace-section-head .count{
  display:inline-grid;place-items:center;
  min-width:16px;height:16px;padding:0 4px;
  border-radius:3px;
  background:var(--surface-2);
  font-family:var(--font-mono);font-size:9.5px;color:var(--ink-3);
}
.trace-section-head .spacer{flex:1}

/* execution track */
.track{position:relative;padding-left:22px}
.track::before{
  content:"";position:absolute;left:6px;top:6px;bottom:10px;
  width:1px;background:var(--line-2);
}
.track li{position:relative;padding-bottom:14px}
.track li:last-child{padding-bottom:0}
.track .marker{
  position:absolute;left:-22px;top:1px;
  display:grid;place-items:center;
  width:13px;height:13px;
  border-radius:50%;
  background:var(--surface);
  border:1px solid var(--line);
}
.track .marker .ic{width:9px;height:9px;stroke-width:2.4;color:var(--green)}
.track .is-now .marker{border-color:var(--amber);background:var(--amber-soft)}
.track .is-now .marker::after{content:"";width:4px;height:4px;border-radius:50%;background:var(--amber);animation:pulse 2.4s ease-in-out infinite}
.track .is-wait .marker{border-style:dashed}
.track .is-wait .marker::after{content:"";width:3px;height:1px;background:var(--ink-3)}
.track .label{display:flex;align-items:baseline;gap:7px;font-size:12px;color:var(--ink-2)}
.track .is-now .label{color:var(--ink);font-weight:550}
.track .label .mono{font-size:9.5px;color:var(--ink-3);margin-left:auto;font-weight:400}
.track .sub{margin-top:2px;font-family:var(--font-mono);font-size:9.5px;color:var(--ink-3)}

/* citations */
.cite-list li{
  padding:9px 0;
  border-bottom:1px solid var(--line-2);
}
.cite-list li:last-child{border-bottom:0}
.cite-top{display:flex;align-items:baseline;gap:8px}
.cite-name{flex:1;min-width:0;font-size:12px;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cite-score{font-family:var(--font-mono);font-size:10px;color:var(--prussian)}
.cite-src{margin-top:2px;font-size:10px;color:var(--ink-3)}

/* agents */
.agent-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid var(--line-2)}
.agent-row:last-child{border-bottom:0}
.agent-ident{flex:1;min-width:0}
.agent-name{font-size:12px;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.agent-name .mono{font-size:9.5px;color:var(--ink-3)}
.agent-kind{margin-top:1px;font-size:10px;color:var(--ink-3)}
.agent-state{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;color:var(--ink-2);white-space:nowrap}
.agent-state .dot{width:5px;height:5px}

.trace-foot{
  margin-top:18px;padding-top:12px;
  border-top:1px solid var(--line-2);
}
.text-link{
  display:inline-flex;align-items:center;gap:5px;
  font-size:11px;color:var(--ink-2);
}
.text-link:hover{color:var(--ink);text-decoration:underline;text-underline-offset:3px}
.text-link .ic{width:12px;height:12px}

/* ---------- toast ---------- */
.toast{
  position:fixed;
  left:50%;bottom:28px;
  z-index:100;
  transform:translate(-50%,10px);
  display:flex;align-items:center;gap:8px;
  max-width:min(420px, calc(100vw - 32px));
  padding:9px 13px;
  border-radius:6px;
  background:var(--ink);
  color:var(--paper);
  font-size:12px;
  box-shadow:0 8px 24px -8px rgba(0,0,0,.4);
  opacity:0;pointer-events:none;
  transition:opacity .18s, transform .18s;
}
html[data-theme="dark"] .toast{background:var(--surface);border:1px solid var(--line)}
.toast.is-visible{opacity:1;transform:translate(-50%,0)}
.toast .ic{width:14px;height:14px;color:var(--green)}

@keyframes pulse{
  0%,100%{opacity:1}
  50%{opacity:.4}
}

/* ---------- responsive ---------- */
@media (max-width:1280px){
  :root{--sessions-w:264px;--trace-w:304px}
  .stream-inner{padding:26px 28px 14px}
  .composer-wrap{padding:8px 24px 12px}
  .chat-head{padding:0 24px}
}

@media (max-width:1180px){
  .app{grid-template-columns:var(--nav-w) var(--sessions-w) minmax(0,1fr)}
  .trace{
    position:fixed;right:0;top:0;bottom:0;
    z-index:60;
    width:var(--trace-w);
    box-shadow:-24px 0 48px -32px rgba(0,0,0,.4);
    transform:translateX(101%);
    transition:transform .22s ease;
  }
  .app.trace-open .trace{transform:translateX(0)}
  .app.trace-collapsed{grid-template-columns:var(--nav-w) var(--sessions-w) minmax(0,1fr)}
  .app.trace-collapsed .trace{opacity:1;pointer-events:auto}
}

@media (max-width:900px){
  .app{grid-template-columns:var(--nav-w) minmax(0,1fr)}
  .sessions{display:none}
  .stream-inner{padding:22px 20px 12px}
  .composer-wrap{padding:8px 16px 12px}
  .chat-head{padding:0 16px}
}

@media (max-width:760px){
  .app{grid-template-columns:1fr;height:100dvh}
  .rail{
    position:fixed;left:0;right:0;bottom:0;
    flex-direction:row;
    width:auto;height:58px;
    padding:0 6px;
    border-top:1px solid var(--rail-line);
    z-index:70;
  }
  .brand,.rail-foot{display:none}
  .rail-nav{
    flex-direction:row;justify-content:space-around;align-items:stretch;
    margin:0;width:100%;gap:0;
  }
  .rail-item{width:auto;flex:1;justify-content:center;padding:6px 0 5px;gap:3px;border-radius:0}
  .rail-item .ic{width:19px;height:19px}
  .rail-item.is-active{background:transparent;color:var(--amber)}
  .rail-item.is-active::before{left:50%;top:0;bottom:auto;transform:translateX(-50%);width:20px;height:2px}
  .chat{padding-bottom:58px}
  .chat-head{min-height:60px}
  .chat-sub .sep,.chat-sub .mono{display:none}
  .status-chip{display:none}
  .stream-inner{padding:18px 14px 10px}
  .entry{padding-left:38px}
  .thread::before{left:15px}
  .node{left:11.5px}
  .thread-foot{margin-left:38px}
  .composer-wrap{padding:6px 10px 10px}
  .composer-hint{display:none}
  .trace{width:min(340px,88vw)}
  .tool-args{display:none}
  .data-table{font-size:12px}
  .prose h3{font-size:17px}
}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important}
}
</style>
