from html.parser import HTMLParser
import re, collections

src = open('ui-v1.html', encoding='utf-8').read()
VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','path','circle','rect','line','polyline','polygon','ellipse','use','stop'}

class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]; self.ids=[]; self.stack_at=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append((d['id'], self.getpos()))
        if tag not in VOID:
            self.stack.append((tag,self.getpos()))
    def handle_startendtag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append((d['id'], self.getpos()))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.errors.append(f'extra </{tag}> at {self.getpos()}')
            return
        if self.stack[-1][0]==tag:
            self.stack.pop()
        else:
            # find match
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    for t in self.stack[i+1:]:
                        self.errors.append(f'unclosed <{t[0]}> opened at {t[1]}, closed by </{tag}> at {self.getpos()}')
                    del self.stack[i:]
                    break
            else:
