import io

path='ui-v1.html'
s=open(path,encoding='utf-8').read()
orig=s

def rep(old,new,count=1):
    global s
    assert old in s, 'MISSING: '+old[:80]
    s=s.replace(old,new,count)

# 1. bus fades near the end instead of dangling
rep(
""".thread::before{
  content:"";
  position:absolute;left:21px;top:10px;bottom:14px;
  width:1px;
  background:var(--line);
}""",
""".thread::before{
  content:"";
  position:absolute;left:21px;top:9px;bottom:6px;
  width:1px;
  background:var(--line);
  -webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 56px),transparent);
  mask-image:linear-gradient(to bottom,#000 calc(100% - 56px),transparent);
}""")

# 2. process rows sit tighter than prose rows
rep(""".entry{position:relative;padding-left:52px;margin-bottom:26px}""",
""".entry{position:relative;padding-left:52px;margin-bottom:26px}
.entry-tool{margin-bottom:14px}""")

# 3. composer background: solid, not a no-op gradient
rep("""  background:linear-gradient(var(--paper) 0%, var(--paper) 100%);""",
"""  background:var(--paper);""")

# 4. typing indicator
rep(""".prose blockquote{""",
""".prose .typing{
  color:var(--ink-3);
  letter-spacing:.18em;
  animation:pulse 1.4s ease-in-out infinite;
}
.prose blockquote{""")

# 5. dark toast contrast
rep("""html[data-theme="dark"] .toast{background:var(--surface);border:1px solid var(--line)}""",
"""html[data-theme="dark"] .toast{background:var(--surface);border:1px solid var(--line);color:var(--ink)}""")

# 6. mobile: only hide the header chip, keep the approval chip
rep("""  .status-chip{display:none}""",
"""  .chat-actions .status-chip{display:none}""")

# 7. heading hierarchy
rep("""<h1 class="sessions-title">会话</h1>""",
"""<h2 class="sessions-title">会话</h2>""")
rep("""<h2 class="chat-title">Q3 客服工单周报</h2>""",
"""<h1 class="chat-title">Q3 客服工单周报</h1>""")

# 8. citation count must match trace list
rep("""<span>知识库 12 段引用</span>""",
"""<span>知识库 3 段引用</span>""")

# 9. consistent progress 3/5
rep("""<span style="width:62%"></span>""",
"""<span style="width:60%"></span>""")

# 10. thread footer wording
rep("""<span>本轮由 main-agent 调度</span>
          <span>·</span>
          <span class="mono">2 remote agents</span>""",
"""<span>本轮由 main-agent 调度</span>
          <span>·</span>
          <span class="mono">2 A2A endpoints</span>""")

# 11. approval copy: pre-approval reads correctly while the review runs
rep("""<p class="approval-action">将周报发布到 <b>#support-weekly</b>，并 @ 值班同事。</p>
                  <dl class="risk-list">
                    <dt>可见范围</dt><dd>频道内 12 名成员</dd>
                    <dt>可撤回</dt><dd>发布后 24 小时内</dd>
                    <dt>发起方</dt><dd>main-agent · run_8f3a2c</dd>
                  </dl>""",
"""<p class="approval-action">批准后，周报将在 <b>editorial-reviewer</b> 审阅通过后自动发布到 <b>#support-weekly</b>，并 @ 值班同事。</p>
                  <dl class="risk-list">
                    <dt>可见范围</dt><dd>频道内 12 名成员</dd>
                    <dt>可撤回</dt><dd>发布后 24 小时内</dd>
                    <dt>触发条件</dt><dd>审阅通过且无阻断问题</dd>
                    <dt>发起方</dt><dd>main-agent · run_8f3a2c</dd>
                  </dl>""")
rep("""<span id="resolvedText">已批准，消息已发送到 #support-weekly。</span>""",
"""<span id="resolvedText">已预批准，审阅通过后将发送到 #support-weekly。</span>""")

# 12. JS copy + initial aria state
rep("""        resolvedText.textContent = '已批准，周报已发送到 #support-weekly。';
        showToast('已批准并发送到 #support-weekly');""",
"""        resolvedText.textContent = '已预批准，审阅通过后将发送到 #support-weekly。';
        showToast('已预批准，审阅通过后自动发送');""")
rep("""        resolvedText.textContent = '已拒绝，main-agent 不会发送这条消息。';""",
"""        resolvedText.textContent = '已拒绝，main-agent 不会发布这条消息。';""")
rep("""  traceToggle.setAttribute('aria-expanded', String(expanded));
  }""",
"""  traceToggle.setAttribute('aria-expanded', String(expanded));
  }""")
rep("""    if (wide.matches) {
      app.classList.remove('trace-collapsed');
      setTraceExpanded(true);
    }
  });""",
"""    if (wide.matches) {
      app.classList.remove('trace-collapsed');
      setTraceExpanded(true);
    } else {
      setTraceExpanded(false);
    }
  });

  setTraceExpanded(wide.matches);""")
rep("""aria-label="切换运行详情面板" aria-expanded="true">""",
"""aria-label="切换运行详情面板" aria-controls="trace" aria-expanded="true">""")

open(path,'w',encoding='utf-8').write(s)
print('patched, delta chars:', len(s)-len(orig))
