path='ui-v1.html'
s=open(path,encoding='utf-8').read()

def rep(old,new,count=1):
    global s
    assert old in s, 'MISSING: '+old[:90]
    s=s.replace(old,new,count)

# table horizontal scroll on narrow screens
rep("""<table class="data-table">
                <caption>按主标签归类，环比相对 Q2</caption>""",
"""<div class="table-wrap">
              <table class="data-table">
                <caption>按主标签归类，环比相对 Q2</caption>""")
rep("""                </tbody>
              </table>""",
"""                </tbody>
              </table>
              </div>""")
rep(""".data-table{
  width:100%;
  margin-top:16px;
  border-collapse:collapse;""",
""".table-wrap{
  margin-top:16px;
  overflow-x:auto;
  overscroll-behavior-x:contain;
}
.data-table{
  width:100%;
  min-width:460px;
  border-collapse:collapse;""")

# page title weight
rep(""".chat-title{
  font-size:16px;font-weight:650;letter-spacing:-.012em;""",
""".chat-title{
  font-size:17px;font-weight:650;letter-spacing:-.012em;""")

# demo-only buttons get a consistent toast hook
rep("""<button class="icon-btn" title="更多操作" aria-label="更多操作">""",
"""<button class="icon-btn" title="更多操作" aria-label="更多操作" data-demo="更多操作（原型演示）">""")
rep("""<button class="composer-tool" title="添加附件">""",
"""<button class="composer-tool" title="添加附件" data-demo="附件选择（原型演示）">""")
rep("""<button class="composer-tool" title="提及智能体">""",
"""<button class="composer-tool" title="提及智能体" data-demo="智能体选择（原型演示）">""")
rep("""<button class="text-link">
          查看完整运行日志""",
"""<button class="text-link" data-demo="完整运行日志（原型演示）">
          查看完整运行日志""")

# copy + demo handlers
rep("""  updateSendState();
  autoGrow();
})();""",
"""  /* ---------- copy ---------- */
  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand('copy');
      showToast('已复制到剪贴板');
    } catch (err) {
      showToast('复制失败，请手动选择文本');
    }
    document.body.removeChild(ta);
  }

  document.querySelectorAll('.copy-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var text = btn.getAttribute('data-copy') || '';
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(function () {
          showToast('已复制到剪贴板');
        }).catch(function () {
          fallbackCopy(text);
        });
      } else {
        fallbackCopy(text);
      }
    });
  });

  /* ---------- demo affordances ---------- */
  document.querySelectorAll('[data-demo]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      showToast(btn.getAttribute('data-demo'));
    });
  });

  updateSendState();
  autoGrow();
})();""")

open(path,'w',encoding='utf-8').write(s)
print('ok')
