/**
 * Sidebar shell: column geometry and global panel navigation.
 * Collapse is a slide plus crossfade:
 * content freezes at its expanded width (inline style) and fades out in place
 * while the sliding column (AppFrame grid tracks) clips it — nothing reflows
 * mid-slide. At settle the wide-only content unmounts and the upper
 * controls enter the 56px rail from the same horizontal offset (one icon each,
 * same top-down order) on one fade that ends with the slide. The bottom-pinned
 * settings control only fades. The workspace/session browsing region between
 * global panel rows and the foot is the `sidebar.workspaces` registrant's,
 * and the foot holds `sidebar.settings` plus `sidebar.footer.action`; the shell
 * hands them the wide flag (plus an expand request callback for the browser).
 * Through the browser's hookContext, the shell also hands it the scroller hook
 * that continues wheel scrolling over the sidebar viewport into its list.
 *
 * The column also owns whether the scroll regions nested in it draw a
 * scrollbar at all: the shell tracks the pointer and rebinds ui-theme's
 * scrollbar indirection away while it is elsewhere, so a list the user is not
 * pointing at carries no bar.
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import clsx from 'clsx'
import {
  FishLogo, IconAppsAddOutlineRegular, IconNewChatOutlineMedium, IconNewChatOutlineRegular,
  IconPanelLeftOutlineRegular, IconPinFillRegular, focusWithoutRing, isBehindModal, isDarwinDesktop, Menu, ShortcutKeys, Toast,
  Tooltip, useModalLayer, writeClipboard,
} from '@deepseek-ai/dsh-client-ui-primitives'
import type { InjectFace, PropsRenderFactories, PropsRenderSlots, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type {
  SidebarPanelActionsOwnerProps, SidebarPanelMetadata, SidebarRootComponentProps, SidebarRootInjected, SidebarSectionHookContext,
  SidebarSectionOwnerProps,
} from './contract/slots.ts'
import { FIXED_PANEL_ID } from './panel-pins.ts'
import { createScrollHandoff } from './scroll-handoff.ts'
import css from './SidebarRoot.module.css'

/** Wide-content unmount delay; matches the 150ms wide-content fade-out. */
const COLLAPSE_SETTLE_MS = 150

/**
 * How long the column's scrollbars stay drawn after the pointer leaves it.
 * The bar is a pointer affordance here, and hiding it on the leave event
 * itself makes it blink out while the pointer is only crossing the column's
 * edge — on the way to the conversation, or around a portalled menu.
 */
const SCROLLBAR_LINGER_MS = 2000

/** Format complete-build metadata for the local brand badge. */
function localBuildVersion(): string | undefined {
  const version = process.env.DSH_CLIENT_VERSION
  if (version === undefined) return undefined
  const commit = process.env.DSH_CLIENT_COMMIT_HASH
  return version
    + (commit === undefined ? '' : `-${commit}`)
    + (process.env.DSH_CLIENT_GIT_DIRTY === 'true' ? '-dirty' : '')
}

type PanelRowProps =
  Pick<SidebarPanelMetadata, 'id' | 'label'>
  & Pick<SidebarSectionOwnerProps, 'wide'>
  & Pick<PropsRuntime<'sidebar'>, 'usePanelInfo'>
  & Pick<InjectFace<SidebarRootInjected>, 'selectPanel' | 'trackEntryClick' | 'setPinned'>
  & { readonly unpinLabel: string; readonly unpinTooltip: string; readonly canUnpin: boolean }
  & PropsRenderFactories

/** Analytics category of an official panel; other panels are never reported. */
function officialEntry(id: string): 'plugin' | 'cron' | undefined {
  if (id === 'plugins') return 'plugin'
  return id === 'schedules' ? 'cron' : undefined
}

/** Each panel row subscribes only to its own selection state. */
function PanelRow({
  id, label, wide, unpinLabel, unpinTooltip, canUnpin, usePanelInfo, selectPanel, setPinned, trackEntryClick, renderFactorySlot,
}: PanelRowProps) {
  const active = usePanelInfo(info => info.activePanelId === id)
  return (
    <div className={clsx(css.panelEntry, wide && css.panelEntryWide, active && css.panelEntryActive)}>
      <Tooltip label={label} delayMs={500} disabled={wide}>
        <button
          type="button"
          className={css.panelRow}
          aria-label={label}
          aria-current={active ? 'page' : undefined}
          onClick={() => {
            const entry = officialEntry(id)
            if (entry !== undefined) trackEntryClick({ menu_name: entry, position: 'sidebar' })
            selectPanel(id)
          }}
        >
          <span className={css.panelGlyph} aria-hidden="true">
            {renderFactorySlot('sidebar.panel.icon', { id, size: wide ? 16 : 18, active })}
          </span>
          {wide && (
            <span className={clsx(css.panelTitle, css.wide)}>
              {label}
            </span>
          )}
        </button>
      </Tooltip>
      {wide && canUnpin && <Tooltip label={unpinTooltip} side="bottom" align="end" delayMs={500} portal>
        <button type="button" className={css.panelUnpin} aria-label={unpinLabel} onClick={(event) => {
          // Unpin is rendered only while this navigation also renders More.
          const navigation = event.currentTarget.closest('nav') as HTMLElement
          const more = navigation.querySelector('button[aria-haspopup="menu"]') as HTMLButtonElement
          focusWithoutRing(more)
          setPinned(id, false)
        }}>
          <IconPinFillRegular size={14} />
        </button>
      </Tooltip>}
    </div>
  )
}

type PanelMoreMenuProps =
  Pick<SidebarSectionOwnerProps, 'wide'>
  & Omit<SidebarPanelActionsOwnerProps, 'onDismiss'>
  & PropsRenderSlots<'sidebar.panellist.actions'>
  & Pick<InjectFace<SidebarRootInjected>, 'trackEntryClick'>
  & { readonly label: string }

/** The panel list's More launcher: a panel-row button whose menu rows come from `sidebar.panellist.actions`. */
function PanelMoreMenu({ wide, label, entries, onOpen, onPinnedChange, trackEntryClick, renderSlot }: PanelMoreMenuProps) {
  const [open, setOpen] = useState(false)
  const onDismiss = (): void => { setOpen(false) }
  return (
    <Menu open={open} onClose={onDismiss} portal autoFocus className={css.moreAnchor} listClassName={css.moreMenu}
      anchor={(
        <Tooltip label={label} delayMs={500} disabled={wide}>
          <button type="button" className={css.panelRow} aria-label={label} aria-haspopup="menu" aria-expanded={open}
            onClick={() => {
              trackEntryClick({ menu_name: 'more', position: 'sidebar' })
              setOpen(value => !value)
            }}>
            <span className={css.panelGlyph} aria-hidden="true"><IconAppsAddOutlineRegular size={wide ? 16 : 18} /></span>
            {wide && <span className={clsx(css.panelTitle, css.wide)}>{label}</span>}
          </button>
        </Tooltip>
      )}>
      {renderSlot('sidebar.panellist.actions', { entries, onOpen, onPinnedChange, onDismiss })}
    </Menu>
  )
}

/**
 * Render the sidebar column shell.
 * @param props - composed slot props (runtime share + injected callbacks, contract/slots.ts).
 * @returns the sidebar element tree.
 */
export function SidebarRoot({
  collapsed,
  width,
  drawer,
  startSession,
  toggleSidebar,
  selectPanel,
  setPinned,
  trackEntryClick,
  useRemoteAccess,
  usePanels,
  useEntryPins,
  useEntryActions,
  useShortcuts,
  usePanelInfo,
  t,
  renderSlot,
  renderFactorySlot,
}: SidebarRootComponentProps) {
  const panels = usePanels(snapshot => snapshot)
  const unpinned = useEntryPins(ids => ids)
  const activePanelId = usePanelInfo(info => info.activePanelId)
  const hasEntryActions = useEntryActions(registered => registered)
  const shortcut = useShortcuts(rows => rows.find(row => row.id === 'sidebar.left.toggle'))
  const newShortcut = useShortcuts(rows => rows.find(row => row.id === 'session.new'))
  // A page whose access snapshot excludes starting a Session offers no New Session affordance.
  const canStartSession = useRemoteAccess('session/create')
  const toggleLabel = collapsed ? t('toggle.open') : t('toggle.collapse')
  // Wide content stays mounted while the collapse animates (fading via
  // .collapsed .wide), unmounts at settle, and remounts right away on expand.
  // A closed drawer retains its content with the rail phase already settled.
  const [settled, setSettled] = useState(collapsed)
  useEffect(() => {
    if (drawer || !collapsed) { setSettled(collapsed); return }
    const timer = window.setTimeout(() => { setSettled(true) }, COLLAPSE_SETTLE_MS)
    return () => { window.clearTimeout(timer) }
  }, [collapsed, drawer])
  const windowsTitlebar = document.documentElement.hasAttribute('data-windows-titlebar')
  const wide = drawer || (windowsTitlebar ? !collapsed : !collapsed || !settled)
  const [scrollHandoff] = useState(createScrollHandoff)
  const sectionHookContext = useMemo<SidebarSectionHookContext>(
    () => ({ useSectionScroller: scrollHandoff.useSectionScroller }), [scrollHandoff],
  )
  // The Windows titlebar hosts the New Session controls while the sidebar is collapsed.
  const openNewSession = (): void => {
    trackEntryClick({ menu_name: 'new_session', position: windowsTitlebar && collapsed ? 'titlebar' : 'sidebar' })
    startSession()
  }
  // The Windows caption menus occupy the strip to the right of these controls
  // (that is what --dsh-windows-menu-start reserves), so a right-side bubble
=== CSS ===
/* Sidebar column: vertical stack, padding 8/6, sidebar
   fill and desktop divider painted by the layout column. Collapse is a
   slide + crossfade, not a morph: the content holds its frozen expanded
   layout (inline width set by the component) and fades in place (.fading)
   while the sliding column (AppFrame grid tracks) clips it; the rail layout
   (.collapsed) only applies after the fade settles, so nothing reflows
   mid-slide. */

.root {
  --dsh-sidebar-inline-padding: 8px;
  --dsh-sidebar-row-padding: 12px;
  --dsh-sidebar-label-gap: 6px;
  --dsh-sidebar-paint-inset: 3px;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 6px var(--dsh-sidebar-inline-padding);
  box-sizing: border-box;
  background: var(--dsw-specific-sidebar-fill);
  color: var(--dsw-alias-label-primary);
  font-size: 14px;
  /* The sidebar is elevated above the conversation surface, so a revealed
     scrollbar uses the l2 pair. .quietBars hides it without changing layout. */
  --dsh-scrollbar-thumb: var(--dsw-alias-scrollbar-bg-l2);
  --dsh-scrollbar-thumb-hover: var(--dsw-alias-scrollbar-hover-l2);
}

:global([data-animating]:not([data-dragging])) .root {
  transition: width var(--ds-transition-duration-slow) var(--ds-ease-in-out);
}

/* macOS desktop: the AppFrame column owns the translucent sidebar tint; an
   opaque fill here would sit on top of it and block the window vibrancy. */
:global([data-platform='darwin']) .root {
  background: transparent;
}

/* Rail geometry (figma rail spec): 36x36 control boxes centered in the 56px
   rail (10px side padding), 12px vertical rhythm, 18px from the rail top to
   the whale's box (24px to the 24-wide whale glyph itself). */
.root.collapsed {
  padding: 18px 10px 6px;
}

/* The brand stays in the sidebar; fixed caption controls survive zero-width collapse. */
:global([data-windows-titlebar]) .root .logoRow {
  height: 40px;
  margin: 0;
  padding: 0;
}

:global([data-windows-titlebar]) .toggle {
  position: fixed;
  top: calc((var(--dsh-windows-titlebar-height) - 28px) / 2);
  left: 12px;
  z-index: 30;
  -webkit-app-region: no-drag;
}

:global([data-windows-titlebar]) .root.collapsed .logoRow {
  height: 0;
}

:global([data-windows-titlebar]) .root:not(.collapsed) .brand {
  padding-left: 8px;
}

:global([data-windows-titlebar]) .brandIdentity {
  transform: translateY(1px);
}

:global([data-windows-titlebar]) .brandMark {
  transform: translateX(1px);
}

:global([data-windows-titlebar]) .brandName {
  font-weight: 400;
}

:global([data-windows-titlebar]) .root.collapsed {
  padding: 0;
}

:global([data-windows-titlebar]) .root:not(.collapsed) .newSession {
  margin-top: 6px;
}

:global([data-windows-titlebar]) .collapsed .panelList,
:global([data-windows-titlebar]) .collapsed .regionArea,
:global([data-windows-titlebar]) .collapsed .footArea {
  display: none;
}

:global(html[data-windows-titlebar]:has([data-sidebar-collapsed='true'])) {
  --dsh-windows-menu-start: 84px;
}

:global([data-windows-titlebar]) .collapsed .newSession {
  position: fixed;
  top: calc((var(--dsh-windows-titlebar-height) - 28px) / 2);
  left: 48px;
  margin: 0;
  padding: 0;
  border: none;
  z-index: 30;
  -webkit-app-region: no-drag;
}

:global([data-windows-titlebar]) .railIn .iconButton,
:global([data-windows-titlebar]) .railIn .newSession {
  animation: none;
}

:global([data-windows-titlebar]) .collapsed .toggle,
:global([data-windows-titlebar]) .collapsed .newSession {
  width: 28px;
  height: 28px;
  border-radius: var(--dsw-radius-sm);
  color: var(--dsw-alias-label-secondary);
}

:global([data-windows-titlebar]) .collapsed .toggle .panelIcon {
  display: inline;
}

/* Scrollbars in the column are a pointer affordance: the shell adds this
   class whenever the pointer is not inside (SidebarRoot.tsx owns the linger),
   and rebinding ui-theme's indirection pair to `transparent` takes the thumb
   out of every scroll region nested under it — the workspace browser's
   session list. `transparent` rather than `display: none` on the bar:
   the reservation (`scrollbar-gutter: stable` on the list) stays in force, so
   revealing the thumb never reflows a row. Rebinding contract and the two
   rendering paths it reaches: ui-theme's README. */
.root.quietBars {
  --dsh-scrollbar-thumb: transparent;
  --dsh-scrollbar-thumb-hover: transparent;
}

/* Collapse phase 1: the whole frozen-width content fades out in place over
   150ms; at settle the children unmount/snap to the rail layout. */
.fading > * {
  opacity: 0;
  transition: opacity 150ms var(--ds-ease-in-out);
}

/* Wide-only content fades back in on expand remount. */
.wide {
  animation: wide-in 200ms var(--ds-ease-in-out);
}

@keyframes wide-in {
  from { opacity: 0; }
}

/* At the 150ms rail settle, the upper controls enter from the former
   rail right edge over the remaining 150ms of the AppFrame track transition.
   The bottom-pinned settings seat shares their opacity timeline but stays
   horizontally fixed. Only a live collapse gets .railIn; a cold collapsed
   render stays static. */
.railIn .iconButton,
.railIn .newSession,
.railIn .panelList,
.railIn .regionArea {
  animation: rail-in 150ms var(--ds-ease-in-out) backwards;
}

.railIn .footArea {
  animation: rail-fade-in 150ms var(--ds-ease-in-out) backwards;
}

@keyframes rail-in {
  from {
    opacity: 0;
    transform: translateX(49px);
  }
}

@keyframes rail-fade-in {
  from { opacity: 0; }
}

/* macOS hiddenInset titlebar: the strip spans the column's top edge (negative
   margins cancel the root padding) so it clears the traffic lights at
   (16, 18). The strip marks itself `data-window-drag` in markup (SidebarRoot), so
   its own run is the column's draggable geometry and no frame band has to match
   the strip's height; the toggle inside subtracts via the base.css rule. */
.topStrip {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: 52px;
  box-sizing: border-box;
  margin: -6px calc(-1 * var(--dsh-sidebar-inline-padding)) 0;
  /* The 2px foot centres the 28px toggle at y 25, level with the collapsed
     seat (ui-layout .leadingSeat, top 11) and the conversation title row, so
     collapse/expand never shifts it vertically. */
  padding: 0 12px 2px;
}

:global(html[data-platform='darwin']:not([data-fullscreen])) .root:not(.collapsed) > .topStrip > .toggle {
  transform: translateX(4px);
}

/* Window fullscreen hides the traffic lights (html[data-fullscreen], desktop
   preload): the toggle takes their spot at the strip's left edge. */
:global([data-fullscreen]) .topStrip {
  justify-content: flex-start;
}

/* The strip's full 52px foot leaves the wordmark too low; the content column
   tucks 12px back under it, still clear of the toggle (28px control centered
   in the strip ends at y 40). */
.topStrip + .logoRow {
  margin-top: -12px;
}

/* Logo row: 8px vertical and leading padding, with no trailing padding or
   bottom margin. Expanded keeps the panel toggle at the
   right edge; the rail gives every control the same base left anchor before

