content.text:
.app{
  display:grid;
  grid-template-columns:var(--sidebar-w) minmax(0,1fr) var(--trace-w);
  height:100dvh;
  min-height:0;
  transition:grid-template-columns .22s ease;
}
.app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr) 0px}
.app.trace-collapsed .trace{opacity:0;pointer-events:none;overflow:hidden}
.app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) var(--trace-w)}
.app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) 0px}

/* ============================================================
   SIDEBAR — single column, DSH-style
   ============================================================ */
.sidebar{
  position:relative;
  display:flex;flex-direction:column;min-height:0;
  padding:6px 8px;
  background:var(--paper-2);
  border-right:1px solid var(--line);
  z-index:20;
  overflow:hidden;
}
.sb-top{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;
  gap:6px;height:44px;padding:0 2px 0 6px;
}
.sb-brand{
  display:flex;align-items:center;gap:8px;min-width:0;
  color:var(--ink);
  font-size:14px;font-weight:650;letter-spacing:-.01em;
  white-space:nowrap;
}
.sb-brand-mark{
  width:22px;height:22px;flex:none;
  fill:none;stroke:currentColor;stroke-width:1.7;
  stroke-linecap:round;stroke-linejoin:round;
}
.sb-brand-mark .hot{fill:var(--amber);stroke:none}
.sb-toggle{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;border-radius:5px;
  color:var(--ink-3);
  transition:color .15s,background .15s;
}
.sb-toggle:hover{color:var(--ink);background:var(--surface-2)}
.sb-toggle .ic{width:16px;height:16px}

.sb-new{
  display:flex;align-items:center;gap:7px;
  height:34px;margin:6px 0 8px;padding:0 10px;
  border:1px solid var(--line);
  border-radius:6px;
  background:var(--surface);
  color:var(--ink);
  font-size:12.5px;font-weight:550;
  box-shadow:var(--shadow-sm);
  white-space:nowrap;
  transition:border-color .15s,background .15s;
}
.sb-new:hover{border-color:var(--ink-3)}
.sb-new .ic{width:15px;height:15px;flex:none}

.sb-nav{display:flex;flex-direction:column;gap:1px;flex:none}
.sb-nav-item{
  display:flex;align-items:center;gap:9px;
  height:31px;padding:0 9px;
  border-radius:5px;
  color:var(--ink-2);
  font-size:12.5px;white-space:nowrap;
  transition:background .12s,color .12s;
}
.sb-nav-item .ic{width:16px;height:16px;flex:none;color:var(--ink-3)}
.sb-nav-item:hover{background:rgba(20,27,32,.045);color:var(--ink)}
html[data-theme="dark"] .sb-nav-item:hover{background:rgba(255,255,255,.05)}
.sb-nav-item.is-active{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:var(--shadow-sm)}
.sb-nav-item.is-active .ic{color:var(--prussian)}

.sb-sessions{
  flex:1;min-height:0;
  display:flex;flex-direction:column;
  margin-top:10px;padding-top:10px;
  border-top:1px solid var(--line);
}
.sb-sessions-head{
  display:flex;align-items:center;justify-content:space-between;
  padding:0 8px 6px;
}
.sb-sessions-head h2{font-size:11px;font-weight:600;color:var(--ink-3);letter-spacing:.03em}
.sb-sessions-head .mono{font-size:9.5px;color:var(--ink-3)}

.search{position:relative;display:block;margin:0 4px 6px}
.search .ic{
  position:absolute;left:9px;top:50%;transform:translateY(-50%);
  width:14px;height:14px;color:var(--ink-3);
}
.search input{
  width:100%;height:32px;padding:0 9px 0 30px;
  border:1px solid transparent;border-radius:6px;
  background:var(--surface-2);color:var(--ink);
  font:inherit;font-size:12px;outline:none;
  transition:border-color .15s,background .15s;
}
.search input::placeholder{color:var(--ink-3)}
.search input:focus{border-color:var(--line);background:var(--surface)}

.session-scroll{flex:1;overflow-y:auto;min-height:0;padding:0 2px 8px}
.session-group{padding-top:6px}
.group-label{padding:0 8px 5px;font-size:10.5px;font-weight:500;color:var(--ink-3);letter-spacing:.03em}
=== media ===
}

@media (max-width:1180px){
  .app{grid-template-columns:var(--sidebar-w) minmax(0,1fr)}
  .app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr)}
  .app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr)}
  .app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr)}
  .trace{
    position:fixed;right:0;top:68px;bottom:0;
    z-index:60;
    width:var(--trace-w);
    box-shadow:-24px 0 48px -32px rgba(0,0,0,.4);
    transform:translateX(101%);
    transition:transform .22s ease;
  }
  .app.trace-open .trace{transform:translateX(0)}
  .app.trace-collapsed .trace{opacity:1;pointer-events:auto}
}

@media (max-width:900px){
  .app,
  .app.sidebar-collapsed,
  .app.trace-collapsed,
  .app.sidebar-collapsed.trace-collapsed{grid-template-columns:minmax(0,1fr)}
  .sidebar{
    position:fixed;left:0;top:0;bottom:0;
    width:min(288px,86vw);
    z-index:80;
    transform:translateX(-100%);
    transition:transform .22s ease;
    box-shadow:24px 0 48px -32px rgba(0,0,0,.45);
  }
  .app.sidebar-open .sidebar{transform:none}
  .mobile-sidebar-btn{display:grid}
  .sidebar-scrim{
    display:block;position:fixed;inset:0;z-index:75;
    background:rgba(20,27,32,.38);
    opacity:0;pointer-events:none;
    transition:opacity .2s;
  }
  .app.sidebar-open .sidebar-scrim{opacity:1;pointer-events:auto}
  .stream-inner{padding:22px 20px 12px}
  .composer-wrap{padding:8px 16px 12px}
  .chat-head{padding:0 16px;gap:12px}
}

@media (max-width:760px){
  .app{height:100dvh}
  .chat-head{min-height:60px}
  .chat-sub{display:none}
  .chat-actions .status-chip{display:none}
  .stream-inner{padding:18px 14px 10px}
  .entry{padding-left:38px}
  .thread::before{left:15px}
  .node{left:11.5px}
  .thread-foot{margin-left:38px}
  .composer-wrap{padding:6px 10px 10px}
  .composer-meta .keyhint{display:none}
  .trace{width:min(340px,88vw);top:60px;bottom:0}
  .tool-args{display:none}
  .data-table{font-size:12px}
  .prose h3{font-size:17px}
}

/* ============================================================
   v2 components
   ============================================================ */

/* turns */
.turn + .turn{margin-top:30px}

/* process cards: tool / vector search */
.entry-proc{margin-bottom:14px}
.entry-proc .node{border-radius:2px}
.kind{
  display:inline-flex;align-items:center;justify-content:center;flex:none;

