{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web/docs/prototypes && cp ui-v4.html ui-v5.html && python3 - <<'PY'
path='ui-v5.html'
s=open(path,encoding='utf-8').read()

def rep(old,new,count=1):
    global s
    assert old in s, 'MISSING: '+old[:120]
    s=s.replace(old,new,count)

rep('<title>Agent Hub · 对话工作台（原型 v4）</title>','<title>Agent Hub · 对话工作台（原型 v5）</title>')
rep('Agent Hub UI prototype v4 — "Dispatch Desk"','Agent Hub UI prototype v5 — "Dispatch Desk"')
rep('<span class="mono">7</span>\n      </div>', '<span class="mono" id="sessionCount">7</span>\n      </div>')

# nav items link to the other-page samples
for page,label,old_demo in [('agents','智能体','智能体页（原型演示）'),('tasks','任务','任务页（原型演示）'),('knowledge','知识库','知识库页（原型演示）')]:
    old=f'''<button class="sb-nav-item" data-demo="{old_demo}" aria-label="{label}" title="{label}">'''
    new=f'''<a class="sb-nav-item" href="ui-v5-pages.html#{page}" aria-label="{label}" title="{label}">'''
    rep(old,new)
    # close the matching anchor: find the item and replace its closing button
    # the next </button> after the new anchor
    idx=s.index(new)
    end=s.index('</button>',idx)
    s=s[:end]+'</a>'+s[end+len('</button>'):]

# settings menu item becomes a link to the settings sample
rep('''<button class="menu-item" role="menuitem" data-demo="设置页（原型演示）">
        <svg class="ic" aria-hidden="true"><use href="#i-sliders"/></svg>设置
      </button>''',
'''<a class="menu-item" role="menuitem" href="ui-v5-pages.html#settings">
        <svg class="ic" aria-hidden="true"><use href="#i-sliders"/></svg>设置
      </a>''')

# CSS for session actions and dialogs
anchor='@media (prefers-reduced-motion:reduce){'
css = r'''/* ============================================================
   v5: session actions
   ============================================================ */
.session-row{position:relative}
.session-row .session{padding-right:30px}
.session-more{
  position:absolute;right:4px;top:7px;
  display:grid;place-items:center;
  width:22px;height:22px;border-radius:4px;
  color:var(--ink-3);
  opacity:0;
  transition:opacity .12s,background .12s,color .12s;
}
.session-row:hover .session-more,
.session-row:focus-within .session-more{opacity:1}
.session-more:hover{background:var(--surface-2);color:var(--ink)}
.session-more .ic{width:14px;height:14px}
.session-row.is-archived .session{opacity:.55}
.session-row.is-renaming .session{display:none}
.session-row.is-renaming .session-more{display:none}
.session-rename{
  display:block;width:100%;height:34px;margin:3px 0;
  padding:0 9px;
  border:1px solid var(--prussian);border-radius:5px;
  background:var(--surface);color:var(--ink);
  font:inherit;font-size:12.5px;outline:none;
}
.session-menu{
  position:fixed;z-index:120;
  width:176px;padding:5px;
  border:1px solid var(--line);border-radius:8px;
  background:var(--surface);
  box-shadow:var(--shadow-md);
  display:none;
}
.session-menu.is-open{display:block}
.session-menu .menu-item{height:32px}
.session-menu .menu-item .ic{width:14px;height:14px}
.dialog-backdrop{
  position:fixed;inset:0;z-index:130;
  display:none;place-items:center;padding:20px;
  background:rgba(20,27,32,.42);
  backdrop-filter:blur(2px);
}
.dialog-backdrop.is-open{display:grid}
.dialog{
  width:min(420px,100%);
  padding:20px;
  border:1px solid var(--line);border-radius:10px;
  background:var(--surface);
  box-shadow:var(--shadow-md);
  outline:none;
}
.dialog h2{font-size:17px;font-weight:650;letter-spacing:-.01em}
.dialog p{margin-top:8px;font-size:12.5px;line-height:1.65;color:var(--ink-2)}
.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}
.btn-danger{background:var(--red);border:1px solid var(--red);color:#FBFAF5}
.btn-danger:hover{filter:brightness(1.06)}
html[data-theme="dark"] .btn-danger{color:#141B20}
@media (hover:none){.session-more{opacity:1}}

'''
rep(anchor, css+anchor)

open(path,'w',encoding='utf-8').write(s)
print('v5 shell/session css patched')
PY
grep -n "ui-v5-pages\|sessionCount\|session-menu" ui-v5.html | head", "description": "Create v5 and add session action styles/links"}

