'''  /* ---------- knowledge document filter ---------- */
  var docSearch = document.getElementById('docSearch');
  var docCategory = document.getElementById('docCategory');

  function filterDocs() {
    var query = docSearch ? docSearch.value.trim().toLowerCase() : '';
    var category = docCategory ? docCategory.value : '';
    var visible = 0;
