{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web/docs/prototypes && python3 - <<'PY'
path='ui-v6.html'
s=open(path,encoding='utf-8').read()
anchor='  /* ---------- approval ---------- */'
assert anchor in s

block = r'''  /* ---------- remote agent streaming drawer ---------- */
  var AGENT_STREAMS = {
    'data-analyst': {
      badge: 'DA',
      name: 'data-analyst',
      skill: 'verify_numbers',
      task: 'task_9b2a',
      duration: '1.2s',
      text: '已加载工单表 128 行，开始核对…\n\n· 总量：128 条 ✓\n· 分类合计：46 + 31 + 24 + 17 + 10 = 128 ✓\n· 环比：+8 − 12 − 3 + 2 − 1 = −6% ✓\n· 平均处理时长：31h → 24h ✓\n· 引用：2 处缺少来源标记\n\n结论：12/12 项数字通过；2 处引用待补，已写入 artifact。'
    },
    'editorial-reviewer': {
      badge: 'ER',
      name: 'editorial-reviewer',
      skill: 'review_copy',
      task: 'task_7c1e',
      duration: '1.8s',
      text: '正在读取周报草稿…\n\n【1】第 1 段\n“本季度共收到 128 条工单，比上季度减少 6%。”\n建议补充统计口径，并注明数据来自 Q3 客服复盘。\n\n【2】第 2 段\n“退款高峰集中在 8 月第二周，与 7 月底促销的退单延后有关。”\n“退款高峰”可以更中性，建议改为“8 月第二周退款工单集中出现”。\n\n【3】结论段\n“建议单独立案跟进。”\n“立案”偏内部术语，建议改为“建议进一步核查”。\n\n整体结论：结构清晰，3 处措辞需调整，未发现事实性问题。'
    }
  };

  function stopAgentStream() {
    if (agentStreamTimer !== null) {
      clearTimeout(agentStreamTimer);
      agentStreamTimer = null;
    }
  }

  function startAgentStream() {
    var data = AGENT_STREAMS[currentAgentKey];
    if (!data) return;
    stopAgentStream();
    agentStreamTextEl.textContent = '';
    streamCursor.style.display = '';
    agentDrawerStatus.className = 'st st-live';
    agentDrawerStatus.innerHTML = '<span class="dot is-live"></span>回放中';
    var chunks = data.text.match(/[\s\S]{1,4}/g) || [];
    var index = 0;
    function tick() {
      if (index >= chunks.length) {
        agentDrawerStatus.className = 'st st-ok';
        agentDrawerStatus.innerHTML = '<span class="dot is-ok"></span>已完成';
        streamCursor.style.display = 'none';
        agentStreamTimer = null;
        return;
      }
      agentStreamTextEl.textContent += chunks[index];
      index += 1;
      agentStream.scrollTop = agentStream.scrollHeight;
      agentStreamTimer = setTimeout(tick, 42);
    }
    tick();
  }

  function openAgentDrawer(key) {
    var data = AGENT_STREAMS[key];
    if (!data) return;
    closeRunDrawer();
    setAccountMenu(false);
    closeSessionMenu();
    currentAgentKey = key;
    agentDrawerBadge.textContent = data.badge;
    agentDrawerName.textContent = data.name;
    agentDrawerSkill.textContent = data.skill;
    agentDrawerTask.textContent = data.task;
    agentDrawerDuration.textContent = data.duration;
    agentDrawerFootTask.textContent = data.task;
    agentScrim.classList.add('is-open');
    agentDrawer.classList.add('is-open');
    agentDrawer.setAttribute('aria-hidden', 'false');
    agentDrawer.focus();
    startAgentStream();
  }

  function closeAgentDrawer() {
    agentScrim.classList.remove('is-open');
    agentDrawer.classList.remove('is-open');
    agentDrawer.setAttribute('aria-hidden', 'true');
    stopAgentStream();
    currentAgentKey = null;
  }

  document.querySelectorAll('[data-agent]').forEach(function (item) {
    item.addEventListener('click', function () {
      openAgentDrawer(item.getAttribute('data-agent'));
    });
    item.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        openAgentDrawer(item.getAttribute('data-agent'));
      }
    });
  });

  document.getElementById('closeAgentDrawer').addEventListener('click', closeAgentDrawer);
  agentScrim.addEventListener('click', closeAgentDrawer);
  replayAgent.addEventListener('click', startAgentStream);

  /* ---------- run trajectory drawer ---------- */
  function setTrajRunState(state) {
    if (!trajRunStatus) return;
    if (state === 'running') {
      trajRunStatus.className = 'st st-live';
      trajRunStatus.innerHTML = '<span class="dot is-live"></span>运行中';
    } else if (state === 'done') {
      trajRunStatus.className = 'st st-ok';
      trajRunStatus.innerHTML = '<span class="dot is-ok"></span>已完成';
    } else if (state === 'rejected') {
      trajRunStatus.className = 'st st-muted';
      trajRunStatus.textContent = '已取消';
    } else {
      trajRunStatus.className = 'st st-live';
      trajRunStatus.innerHTML = '<span class="dot is-live"></span>待审批';
    }
  }

  function setTrajApprovalState(state) {
    if (!trajApprovalStatus) return;
    if (state === 'approved') {
      trajApprovalStatus.innerHTML = '<span class="st st-ok">已批准</span>';
    } else if (state === 'sent') {
      trajApprovalStatus.innerHTML = '<span class="st st-ok"><span class="dot is-ok"></span>已发送</span>';
    } else if (state === 'rejected') {
      trajApprovalStatus.innerHTML = '<span class="st st-error"><span class="dot is-warn"></span>已拒绝</span>';
    } else {
      trajApprovalStatus.innerHTML = '<span class="st st-live"><span class="dot is-live"></span>待审批</span>';
    }
  }

  function openRunDrawer() {
    closeAgentDrawer();
    setAccountMenu(false);
    closeSessionMenu();
    runScrim.classList.add('is-open');
    runDrawer.classList.add('is-open');
    runDrawer.setAttribute('aria-hidden', 'false');
    var scroller = runDrawer.querySelector('.run-scroll');
    if (scroller) scroller.scrollTop = 0;
    runDrawer.focus();
  }

  function closeRunDrawer() {
    runScrim.classList.remove('is-open');
    runDrawer.classList.remove('is-open');
    runDrawer.setAttribute('aria-hidden', 'true');
  }

  openRunEvents.addEventListener('click', openRunDrawer);
  document.getElementById('closeRunEvents').addEventListener('click', closeRunDrawer);
  runScrim.addEventListener('click', closeRunDrawer);

  var trajFilter = 'all';
  var trajQuery = '';

  function filterTrajectory() {
    document.querySelectorAll('.traj-row').forEach(function (row) {
      var kind = row.getAttribute('data-kind');
      var text = row.textContent.toLowerCase();
      var match = (trajFilter === 'all' || kind === trajFilter)
        && (trajQuery === '' || text.indexOf(trajQuery) !== -1);
      row.hidden = !match;
    });
    var any = false;
    document.querySelectorAll('.traj-turn').forEach(function (turn) {
      var visible = Array.prototype.some.call(turn.querySelectorAll('.traj-row'), function (row) {
        return !row.hidden;
      });
      turn.hidden = !visible;
      if (visible) any = true;
    });
    if (trajEmpty) trajEmpty.hidden = any;
  }

  document.querySelectorAll('[data-traj-filter]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      trajFilter = btn.getAttribute('data-traj-filter');
      document.querySelectorAll('[data-traj-filter]').forEach(function (b) {
        b.classList.toggle('is-active', b === btn);
      });
      filterTrajectory();
    });
  });

  if (trajSearch) {
    trajSearch.addEventListener('input', function () {
      trajQuery = trajSearch.value.trim().toLowerCase();
      filterTrajectory();
    });
  }

  trajDuration.addEventListener('click', function () {
    var equal = trajTrack.classList.toggle('is-equal');
    trajDuration.classList.toggle('is-active', !equal);
    trajDuration.setAttribute('aria-pressed', String(!equal));
    trajDuration.textContent = equal ? '等宽' : '实际时长';
  });

  var trajCollapsed = false;
  trajCollapse.addEventListener('click', function () {
    trajCollapsed = !trajCollapsed;
    document.querySelectorAll('.traj-turn').forEach(function (turn) {
      turn.open = !trajCollapsed;
    });
    trajCollapse.textContent = trajCollapsed ? '展开回合' : '折叠回合';
    trajCollapse.setAttribute('aria-pressed', String(trajCollapsed));
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      closeRunDrawer();
      closeAgentDrawer();
    }
  });

  /* ---------- approval ---------- */'''

s=s.replace(anchor, block, 1)
open(path,'w',encoding='utf-8').write(s)
print('v6 drawer js inserted; lines:', s.count(chr(10))+1)
PY", "description": "Add agent stream and trajectory drawer logic"}

