.agent-card-head{display:flex;align-items:flex-start;gap:9px}
.agent-card-ident{flex:1;min-width:0}
.agent-card-head .agent-badge{width:30px;height:30px;font-size:10px}
.agent-card-head .st{margin-left:auto;flex:none}
.agent-name{font-size:13px;font-weight:650;letter-spacing:-.005em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
