.agent-card-url .ic{width:12;height:12;flex:none}
.agent-card-skills{display:flex;flex-wrap:wrap;gap:5px}
.agent-card-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0;padding-top:9px;border-top:1px solid var(--line-2)}
.agent-card-meta dt{font-size:9px;color:ink-3;letter-spacing:.02em}
.agent-card-meta dd{margin-top:2px;font-size:10.5px;color:ink-2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
