.vector-meta{
  padding-bottom:5px;
  font-family:var(--font-mono);
  font-size:9.5px;color:var(--ink-3);
}
.vhit{padding:6px 0;border-bottom:1px dashed var(--line-2);font-size:12px}
.vhit:last-of-type{border-bottom:0}
.vhit-main{display:flex;align-items:baseline;gap:8px}
