.vhit-score{font-family:var(--font-mono);font-size:10.5px;color:var(--prussian)}
.vhit-sub{
  margin-top:2px;
  font-family:var(--font-mono);
  font-size:9.5px;color:var(--ink-3);
}

/* A2A delegation group */
.delegation{
  border:1px solid var(--line);
  border-left:3px solid var(--prussian);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.delegation-head{
  display:flex;align-items:center;gap:7px;flex-wrap:wrap;
  padding:10px 14px;
  border-bottom:1px solid var(--line-2);
  background:var(--surface-2);
}
.delegation-title{font-size:12.5px;font-weight:650;letter-spacing:-.005em}
.delegation-count{font-size:10.5px;color:var(--ink-3)}
.delegation-head .spacer{flex:1}
.delegation-state{font-family:var(--font-mono);font-size:9.5px;color:var(--ink-3)}
.a2a-row{
  display:flex;align-items:flex-start;gap:10px;
  padding:12px 14px;
  border-bottom:1px solid var(--line-2);
}
.a2a-row + .a2a-row{border-bottom:0}
.a2a-row-ident{flex:1;min-width:0}
.a2a-row-ident .a2a-name{font-size:12.5px}
.a2a-row-ident .a2a-task{font-size:11.5px;margin-top:2px}
.a2a-row-state{
  display:flex;flex-direction:column;align-items:flex-end;gap:3px;
  flex:none;padding-top:1px;
}
.a2a-row-meta{font-family:var(--font-mono);font-size:9px;color:var(--ink-3);white-space:nowrap}
.a2a-status.is-done{color:var(--green)}
.a2a-row-result{
  display:flex;align-items:center;gap:5px;
  margin-top:6px;
  font-size:10.5px;color:var(--green);
}
.a2a-row-result .ic{width:11px;height:11px;stroke-width:2.2}
.delegation-foot{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  padding:8px 14px;
  border-top:1px solid var(--line-2);
  background:var(--surface-2);
  font-family:var(--font-mono);
  font-size:9.5px;color:var(--ink-3);
}
.delegation-foot .spacer{flex:1}

/* token usage under the composer */
.composer-meta{
  display:flex;align-items:center;justify-content:space-between;
  gap:6px 18px;flex-wrap:wrap;
  margin-top:8px;padding:0 3px;
  font-size:10.5px;color:var(--ink-3);
}
.keyhint{display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
.usage{
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
  margin-left:auto;
  font-size:10.5px;color:var(--ink-3);
}
.usage b{
  font-family:var(--font-mono);
  font-size:10px;font-weight:500;color:var(--ink-2);
  font-variant-numeric:tabular-nums;
}
.usage-sep{opacity:.5}

@media (max-width:760px){
  .prompt-bubble{max-width:88%;font-size:14px}
  .user-turn{margin-bottom:24px}
  .composer-meta .keyhint{display:none}
  .usage{margin-left:0;font-size:10px}
  .delegation-state{display:none}
  .a2a-row-state{flex-direction:row;align-items:center;gap:7px}
  .a2a-row-result{font-size:10px}
}
