    btn.addEventListener('click', function () {
      if (btn.disabled) return;
      selectWorkflow(btn.getAttribute('data-workflow'), true);
    });
  });

  document.querySelectorAll('[data-knowledge]').forEach(function (btn) {
    btn.addEventListener('click', toggleKnowledge);
  });

  modelBtn.addEventListener('click', function () {
    if (modelMenu.hidden) openModelMenu();
    else closeModelMenu();
  });

  document.querySelectorAll('[data-model]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      setModel(btn.getAttribute('data-model'));
    });
  });

  document.querySelectorAll('[data-effort]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      setEffort(btn.getAttribute('data-effort'));
    });
  });

  document.addEventListener('click', function (event) {
    if (!event.target.closest('.plus-wrap')) closeComposerMenu();
    if (!event.target.closest('.model-wrap')) closeModelMenu();
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      closeComposerMenu();
      closeModelMenu();
    }
  });

  window.addEventListener('hashchange', applyWorkflowHash);

  renderComposerContext();

  /* ---------- composer ---------- */'''
