            '<select class="select wf-name" data-step-field="name">' + stepNameOptions(step.type, step.name) + '</select>' +
          '</div>' +
          '<label class="wf-edit-approval"><input type="checkbox" data-step-field="approval"' + (step.approval ? ' checked' : '') + '> 写操作需审批</label>' +
        '</div>' +
        '<div class="wf-edit-tools">' +
          '<button class="wf-step-btn" data-step-action="up" aria-label="上移"' + (index === 0 ? ' disabled' : '') + '>↑</button>' +
          '<button class="wf-step-btn" data-step-action="down" aria-label="下移"' + (index === editingSteps.length - 1 ? ' disabled' : '') + '>↓</button>' +
          '<button class="wf-step-btn is-danger" data-step-action="remove" aria-label="删除步骤">×</button>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  wfEditSteps.addEventListener('change', function (event) {
    var target = event.target;
    var row = target.closest('.wf-edit-step');
    if (!row) return;
    var index = Number(row.getAttribute('data-index'));
    var field = target.getAttribute('data-step-field');
    if (!field || !editingSteps[index]) return;
    if (field === 'type') {
      editingSteps[index].type = target.value;
      editingSteps[index].name = STEP_CATALOG[target.value].options[0];
      renderEditSteps();
    } else if (field === 'name') {
      editingSteps[index].name = target.value;
    } else if (field === 'approval') {
      editingSteps[index].approval = target.checked;
    }
  });

  wfEditSteps.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-step-action]');
    if (!btn) return;
    var row = btn.closest('.wf-edit-step');
    var index = Number(row.getAttribute('data-index'));
    var action = btn.getAttribute('data-step-action');
    if (action === 'remove') {
      editingSteps.splice(index, 1);
    } else if (action === 'up' && index > 0) {
      var prev = editingSteps[index - 1];
      editingSteps[index - 1] = editingSteps[index];
      editingSteps[index] = prev;
    } else if (action === 'down' && index < editingSteps.length - 1) {
      var next = editingSteps[index + 1];
      editingSteps[index + 1] = editingSteps[index];
      editingSteps[index] = next;
    }
