{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web/docs/prototypes && python3 - <<'PY'
from html.parser import HTMLParser
import re, collections
for fn in ['ui-v7.html','ui-v7-pages.html']:
    src=open(fn,encoding='utf-8').read()
    VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','path','circle','rect','line','polyline','polygon','ellipse','use','stop'}
    class P(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True); self.stack=[]; self.err=[]; self.ids=[]
        def handle_starttag(self,t,a):
            d=dict(a)
            if 'id' in d:self.ids.append(d['id'])
            if t not in VOID:self.stack.append((t,self.getpos()))
        def handle_startendtag(self,t,a):
            d=dict(a)
            if 'id' in d:self.ids.append(d['id'])
        def handle_endtag(self,t):
            if t in VOID:return
            if not self.stack:self.err.append(('extra',t,self.getpos()));return
            if self.stack[-1][0]==t:self.stack.pop()
            else:self.err.append(('mismatch',t,self.getpos(),self.stack[-3:]))
    p=P();p.feed(src)
    styles=re.findall(r'<style>(.*?)</style>',src,re.S)
    css=''.join(styles)
    js=''.join(re.findall(r'<script>(.*?)</script>',src,re.S))
    open('/tmp/'+fn+'.js','w',encoding='utf-8').write(js)
    ids=set(p.ids)
    refs=sorted(set(re.findall(r"getElementById\('([^']+)'\)",js)))
    print(fn)
    print(' tag:',p.err or 'none','| unclosed:',p.stack or 'none','| dup:',[k for k,v in collections.Counter(p.ids).items() if v>1] or 'none')
    print(' css:',css.count('{'),css.count('}'),'| styles:',len(styles),'| missing:',[r for r in refs if r not in ids] or 'none')
    print(' stale links:',src.count('ui-v5')+src.count('ui-v6'),'| @智能体:',src.count('提及智能体'))
    if fn=='ui-v7.html':
        print(' workflow nav:',src.count('href="ui-v7-pages.html#workflows"'),'| + menu:',src.count('id="composerMenu"'),'| model:',src.count('id="modelBtn"'),'| no @ button:', 'data-demo="智能体选择' not in src)
    else:
        print(' workflow nav/page:',src.count('data-page="workflows"'),'| titles contains:',"workflows: '工作流'" in src,'| editor:',src.count('id="wfEditor"'))
