}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
a{color:inherit;text-decoration:none}
ul,ol,dl,dd{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,p{margin:0}
svg{display:block}
[hidden]{display:none!important}
:focus-visible{outline:2px solid var(--prussian);outline-offset:2px;border-radius:3px}
::selection{background:var(--amber-soft);color:var(--ink)}
*{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--line);border-radius:10px;border:2px solid transparent;background-clip:padding-box}
.ic{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}
.mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.spacer{flex:1}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

/* ---------- progress / theme button ---------- */
.theme-icon-light{display:none}
html[data-theme="dark"] .theme-icon-light{display:block}
html[data-theme="dark"] .theme-icon-dark{display:none}

/* ---------- app shell ---------- */
.admin-app{
  display:grid;grid-template-columns:252px minmax(0,1fr);
  height:100vh;overflow:hidden;
}
.rail{
  position:relative;z-index:60;
  display:flex;flex-direction:column;min-height:0;
  padding:12px 10px 10px;
  color:var(--rail-text);background:var(--rail);
  border-right:1px solid var(--rail-line);
}
.rail-brand{display:flex;align-items:center;gap:8px;padding:2px 6px 12px}
.brand-lockup{display:flex;align-items:center;gap:9px;min-width:0}
.brand-mark{
  display:grid;place-items:center;flex:none;
  width:30px;height:30px;border:1px solid var(--rail-line);border-radius:6px;
  background:var(--rail-2);color:var(--rail-amber);
}
.brand-mark .ic{width:18px;height:18px;stroke-width:1.6}
.brand-text{display:flex;flex-direction:column;gap:1px;min-width:0}
.brand-text b{font-size:13.5px;font-weight:650;letter-spacing:-.015em;white-space:nowrap}
.brand-text small{font-size:9.5px;color:var(--rail-muted);letter-spacing:.02em}
.admin-badge{
  flex:none;margin-left:auto;padding:2px 5px;
  border:1px solid rgba(212,160,74,.34);border-radius:3px;
  color:var(--rail-amber);font-size:8.5px;line-height:1.3;
}
.rail-back{
  display:flex;align-items:center;gap:6px;
  margin:0 4px 12px;padding:6px 7px;
  border:1px solid var(--rail-line);border-radius:5px;
  color:var(--rail-muted);font-size:10.5px;
  transition:color .12s,background .12s;
}
.rail-back:hover{color:var(--rail-text);background:var(--rail-active)}
.rail-back .ic{width:13px;height:13px}

.rail-nav{display:flex;flex-direction:column;gap:12px;min-height:0;overflow-y:auto;padding:0 2px 12px}
.rail-group{display:flex;flex-direction:column;gap:2px}
.rail-label{padding:0 8px 4px;font-size:9px;color:var(--rail-faint);letter-spacing:.03em}
.rail-link{
  position:relative;display:flex;align-items:center;gap:8px;
  width:100%;height:31px;padding:0 8px;border-radius:5px;
  text-align:left;color:var(--rail-muted);font-size:11.5px;
  transition:background .12s,color .12s;
}
.rail-link .ic{width:15px;height:15px;color:var(--rail-faint);transition:color .12s}
.rail-link:hover{background:var(--rail-active);color:var(--rail-text)}
.rail-link:hover .ic{color:var(--rail-muted)}
.rail-link.is-active{background:var(--rail-active);color:var(--rail-text);font-weight:550}
.rail-link.is-active::before{
  content:"";position:absolute;left:-2px;top:7px;bottom:7px;width:2px;
  border-radius:2px;background:var(--rail-amber);
}
.rail-link.is-active .ic{color:var(--rail-amber)}
.rail-count{
  margin-left:auto;font-family:var(--font-mono);font-size:8.5px;
  color:var(--rail-faint);
}
.rail-link.is-active .rail-count{color:var(--rail-muted)}

.rail-foot{margin-top:auto;padding:9px 2px 2px;border-top:1px solid var(--rail-line)}
.rail-health{
  display:flex;align-items:center;gap:6px;
  padding:4px 7px 10px;font-size:9.5px;color:var(--rail-muted);
}
.rail-health .dot{width:5px;height:5px;background:#8DBBA0;border-radius:50%;box-shadow:0 0 0 3px rgba(141,187,160,.12)}
.rail-health .mono{margin-left:auto;font-size:8.5px;color:var(--rail-faint)}
.rail-account{
  display:flex;align-items:center;gap:8px;
  padding:8px 7px;border-top:1px solid var(--rail-line);
}
.rail-avatar{
  display:grid;place-items:center;flex:none;
  width:27px;height:27px;border-radius:50%;
  background:var(--rail-2);border:1px solid var(--rail-line);
  color:var(--rail-text);font-family:var(--font-mono);font-size:9px;
}
.rail-account-main{flex:1;min-width:0}
.rail-account-main b{display:block;font-size:11px;font-weight:550;color:var(--rail-text)}
.rail-account-main small{display:block;margin-top:1px;font-size:8.5px;color:var(--rail-faint)}
.rail-logout{
  display:grid;place-items:center;width:25px;height:25px;
  border-radius:4px;color:var(--rail-faint);
}
.rail-logout:hover{background:var(--rail-active);color:var(--rail-text)}
.rail-logout .ic{width:14px;height:14px}

.rail-scrim{
  display:none;position:fixed;inset:0;z-index:50;
  background:rgba(7,11,13,.55);
}

/* ---------- main / topbar ---------- */
.admin-main{display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--paper)}
.topbar{
  flex:none;display:flex;align-items:center;gap:14px;
  height:58px;padding:0 26px;
  background:var(--surface);border-bottom:1px solid var(--line);
}
.mobile-menu{display:none}
.crumb{
  display:flex;align-items:center;gap:8px;min-width:0;
  font-size:10.5px;color:var(--ink-3);white-space:nowrap;
}
.crumb .ic{width:11px;height:11px;color:var(--line)}
.crumb b{font-weight:550;color:var(--ink-2);overflow:hidden;text-overflow:ellipsis}
.topbar-tools{display:flex;align-items:center;gap:7px;margin-left:auto;min-width:0}
.env-chip{
  display:inline-flex;align-items:center;gap:5px;
  height:25px;padding:0 7px;
  border:1px solid var(--line);border-radius:4px;
  background:var(--surface-2);font-size:9px;color:var(--ink-3);
  white-space:nowrap;
}
.env-chip .dot{width:4px;height:4px;background:var(--green);border-radius:50%}
.global-search{
  display:flex;align-items:center;gap:6px;
  width:240px;height:29px;padding:0 8px;
  border:1px solid var(--line);border-radius:5px;background:var(--paper);
}
.global-search .ic{width:13px;height:13px;color:var(--ink-3)}
.global-search input{
  width:100%;min-width:0;border:0;outline:none;background:transparent;
  color:var(--ink);font:inherit;font-size:10.5px;
}
.global-search input::placeholder{color:var(--ink-3)}
.icon-btn{
  display:grid;place-items:center;flex:none;
  width:29px;height:29px;border:1px solid transparent;border-radius:5px;
  color:var(--ink-3);transition:background .12s,color .12s,border-color .12s;
}
.icon-btn:hover{background:var(--surface-2);color:var(--ink);border-color:var(--line-2)}
.icon-btn .ic{width:15px;height:15px}
.bell{position:relative}
.bell-dot{position:absolute;top:6px;right:6px;width:5px;height:5px;border-radius:50%;background:var(--amber);border:1px solid var(--surface)}
.topbar-avatar{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;margin-left:2px;border-radius:50%;
  background:var(--ink);color:var(--paper);
  font-family:var(--font-mono);font-size:9px;
}

/* ---------- page scaffold ---------- */
.admin-scroll{flex:1;min-height:0;overflow-y:auto}
.admin-page{
  width:100%;max-width:1240px;margin:0 auto;
  padding:28px 34px 64px;
}
.admin-page-head{
  display:flex;align-items:flex-end;justify-content:space-between;gap:24px;
  padding-bottom:16px;border-bottom:1px solid var(--line);
}
.page-title{font-size:23px;font-weight:650;letter-spacing:-.022em;line-height:1.2}
.page-sub{margin-top:5px;font-size:11.5px;line-height:1.6;color:var(--ink-3);max-width:68ch}
.head-actions{display:flex;align-items:center;gap:7px;flex:none;flex-wrap:wrap}

/* ---------- buttons ---------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:5px;
  height:30px;padding:0 11px;
  border:1px solid transparent;border-radius:4px;
  font-size:11px;font-weight:500;white-space:nowrap;
  transition:background .12s,color .12s,border-color .12s;
}
.btn .ic{width:13px;height:13px}
.btn-primary{background:var(--btn-bg);color:var(--btn-fg)}
.btn-primary:hover{background:var(--prussian);color:var(--surface)}
html[data-theme="dark"] .btn-primary:hover{background:var(--amber);color:#11181D}
.btn-outline{border-color:var(--line);background:var(--surface);color:var(--ink-2)}
.btn-outline:hover{border-color:var(--ink-3);color:var(--ink);background:var(--surface-2)}
.btn-ghost{border-color:transparent;background:transparent;color:var(--ink-2)}
.btn-ghost:hover{background:var(--surface-2);color:var(--ink)}
.btn-danger{background:var(--red-soft);color:var(--red)}
.btn-sm{height:25px;padding:0 8px;font-size:10px;border-radius:3px}
.btn-sm .ic{width:11px;height:11px}
.btn[disabled]{opacity:.42;cursor:not-allowed}
.text-link{
  display:inline-flex;align-items:center;gap:4px;
  color:var(--prussian);font-size:10px;
}
.text-link:hover{text-decoration:underline;text-underline-offset:2px}
.text-link .ic{width:10px;height:10px}
.text-link.is-danger{color:var(--red)}

/* ---------- status / badges ---------- */
.st{
  display:inline-flex;align-items:center;gap:4px;
  height:19px;padding:0 6px;
  border:1px solid transparent;border-radius:3px;
  font-size:9px;font-weight:500;white-space:nowrap;
}
.st .dot{width:4px;height:4px;border-radius:50%}
.st-ok{background:var(--green-soft);color:var(--green)}
.st-ok .dot{background:var(--green)}
.st-live{background:var(--amber-soft);color:var(--amber-text)}
.st-live .dot{background:var(--amber);animation:pulse 2.4s ease-in-out infinite}
.st-warn{background:var(--amber-soft);color:var(--amber-text)}
.st-warn .dot{background:var(--amber)}
.st-error{background:var(--red-soft);color:var(--red)}
.st-error .dot{background:var(--red)}
.st-muted{background:var(--surface-2);color:var(--ink-3);border-color:var(--line-2)}
.st-muted .dot{background:var(--ink-3)}
@keyframes pulse{0%,100%{opacity:.45}50%{opacity:1}}

.role-badge{
  display:inline-flex;align-items:center;
  height:20px;padding:0 6px;
  border:1px solid var(--line-2);border-radius:3px;
  background:var(--surface-2);
  font-size:9px;color:var(--ink-2);white-space:nowrap;
}
.role-badge.admin{background:var(--amber-soft);border-color:rgba(169,116,31,.2);color:var(--amber-text)}
.role-badge.ops{background:var(--prussian-soft);border-color:rgba(23,70,94,.16);color:var(--prussian)}
.role-badge.support{background:var(--green-soft);border-color:rgba(61,106,78,.14);color:var(--green)}
.role-badge.editor{background:var(--mcp-soft);border-color:rgba(90,78,114,.16);color:var(--mcp)}
.role-badge.auditor{background:var(--surface-2);color:var(--ink-3)}
.type-chip{
  display:inline-flex;align-items:center;height:18px;padding:0 5px;
  border:1px solid var(--line-2);border-radius:3px;
  background:var(--surface-2);font-size:8.5px;color:var(--ink-3);
}
.type-chip.directory{background:var(--prussian-soft);border-color:transparent;color:var(--prussian)}
.type-chip.button{background:var(--amber-soft);border-color:transparent;color:var(--amber-text)}
.badge{
  display:inline-flex;align-items:center;height:18px;padding:0 5px;
  border-radius:3px;background:var(--surface-2);
  font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3);
}
.tag{
  display:inline-flex;align-items:center;height:17px;padding:0 4px;
  border:1px solid var(--line-2);border-radius:3px;
  background:var(--surface-2);font-family:var(--font-mono);font-size:8px;color:var(--ink-3);
}

/* ---------- metric strip ---------- */
.metric-strip{
  display:grid;grid-template-columns:repeat(5,minmax(0,1fr));
  margin:18px 0 18px;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);
}
.metric{padding:12px 16px 11px;border-right:1px solid var(--line-2)}
.metric:last-child{border-right:0}
.metric-label{display:block;font-size:9px;color:var(--ink-3);letter-spacing:.02em}
.metric-value{
  display:block;margin-top:2px;
  font-family:var(--font-mono);font-size:22px;font-weight:500;line-height:1.2;
  color:var(--ink);font-variant-numeric:tabular-nums;
}
.metric-value small{font-family:var(--font-sans);font-size:9px;font-weight:400;color:var(--ink-3);margin-left:4px}
.metric-foot{display:flex;align-items:center;gap:5px;margin-top:3px;font-size:8.5px;color:var(--ink-3)}
.delta{color:var(--green);font-family:var(--font-mono)}
.delta.is-warn{color:var(--amber-text)}
.delta.is-bad{color:var(--red)}

/* ---------- panels ---------- */
.grid-2{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:14px;margin-top:14px}
.panel{
  min-width:0;
  border:1px solid var(--line);border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
}
.panel-head{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  min-height:44px;padding:9px 14px;
  border-bottom:1px solid var(--line-2);
}
.panel-head h2{font-size:12px;font-weight:600;letter-spacing:-.005em}
.panel-head p{font-size:9.5px;color:var(--ink-3);margin-top:1px}
.panel-meta{font-size:9px;color:var(--ink-3)}
.panel-head .spacer{flex:1}
.panel-body{padding:14px}
.panel-foot{
  display:flex;align-items:center;gap:8px;
  padding:8px 14px;border-top:1px solid var(--line-2);
  background:var(--surface-2);font-size:9px;color:var(--ink-3);
}

/* chart */
.chart-bars{
  display:flex;align-items:stretch;gap:10px;
  height:156px;padding:12px 4px 0;
}
.bar-col{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:5px;min-width:0}
.bar{
  width:100%;max-width:36px;height:var(--h);min-height:4px;
  border-radius:2px 2px 0 0;background:var(--prussian);
  transition:opacity .12s;
}
.bar-col:hover .bar{opacity:.72}
.bar-col.is-today .bar{background:var(--amber)}
.bar-label{font-family:var(--font-mono);font-size:8px;color:var(--ink-3)}
.bar-value{font-family:var(--font-mono);font-size:8px;color:var(--ink-3);margin-top:auto}

/* status list */
.status-list{display:flex;flex-direction:column}
.status-row{
  display:flex;align-items:center;gap:8px;
  padding:8px 0;border-bottom:1px solid var(--line-2);
  font-size:10.5px;
}
.status-row:last-child{border-bottom:0;padding-bottom:0}
.status-row:first-child{padding-top:0}
.status-dot{width:5px;height:5px;border-radius:50%;flex:none}
.status-dot.ok{background:var(--green)}
.status-dot.warn{background:var(--amber)}
.status-dot.bad{background:var(--red)}
.status-name{flex:1;color:var(--ink-2)}
.status-meta{font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3)}
.status-state{font-size:9px;color:var(--green);white-space:nowrap}
.status-state.warn{color:var(--amber-text)}
.status-state.bad{color:var(--red)}

/* recent audit mini */
.audit-mini{display:flex;flex-direction:column}
.audit-mini-row{
  display:flex;align-items:flex-start;gap:8px;
  padding:8px 0;border-bottom:1px solid var(--line-2);
}
.audit-mini-row:last-child{border-bottom:0;padding-bottom:0}
.audit-mini-row:first-child{padding-top:0}
.audit-mini-time{width:58px;flex:none;font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3);padding-top:2px}
.audit-mini-main{flex:1;min-width:0;font-size:10.5px;line-height:1.5;color:var(--ink-3)}
.audit-mini-main b{font-weight:550;color:var(--ink-2)}
.audit-mini-res{
  margin-top:2px;font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}

/* todo */
.todo-list{display:flex;flex-direction:column}
.todo-row{
  display:flex;align-items:center;gap:9px;
  padding:9px 0;border-bottom:1px solid var(--line-2);
  font-size:10.5px;color:var(--ink-2);
}
.todo-row:last-child{border-bottom:0;padding-bottom:0}
.todo-row:first-child{padding-top:0}
.todo-row:hover{color:var(--ink)}
.todo-row .ic{width:14px;height:14px;color:var(--ink-3)}
.todo-row b{font-family:var(--font-mono);font-weight:500;color:var(--ink);font-size:10px}
.todo-row .spacer{flex:1}
.todo-row .text-link{flex:none}

/* ---------- toolbar / forms ---------- */
.toolbar{
  display:flex;align-items:center;gap:7px;flex-wrap:wrap;
  margin:14px 0 10px;
}
.summary-line{
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
  margin-top:14px;font-size:10px;color:var(--ink-3);
}
.summary-line b{font-family:var(--font-mono);font-size:11px;font-weight:500;color:var(--ink-2)}
.summary-line .sep{opacity:.45}
.search-field{
  display:flex;align-items:center;gap:6px;
  height:29px;min-width:210px;padding:0 8px;
  border:1px solid var(--line);border-radius:5px;background:var(--surface);
}
.search-field .ic{width:13px;height:13px;color:var(--ink-3);flex:none}
.search-field input{
  flex:1;min-width:0;border:0;outline:none;background:transparent;
  font:inherit;font-size:10.5px;color:var(--ink);
}
.search-field input::placeholder{color:var(--ink-3)}
.select,.input,.textarea{
  height:30px;padding:0 8px;
  border:1px solid var(--line);border-radius:4px;
  background:var(--surface);color:var(--ink);
  font:inherit;font-size:10.5px;
  outline:none;
  transition:border-color .12s;
}
.select:focus,.input:focus,.textarea:focus{border-color:var(--ink-3)}
.select{cursor:pointer}
.textarea{height:auto;min-height:70px;padding:7px 8px;resize:vertical;line-height:1.55}
.field{display:flex;flex-direction:column;gap:4px;min-width:0}
.field > span{font-size:9px;color:var(--ink-3)}
.field > small{font-size:8.5px;color:var(--ink-3)}
.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}
.field-row{
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:10px 0;border-bottom:1px solid var(--line-2);
}
.field-row:last-child{border-bottom:0;padding-bottom:0}
.field-row:first-child{padding-top:0}
.field-row-main{min-width:0}
.field-row-main b{display:block;font-size:10.5px;font-weight:550;color:var(--ink-2)}
.field-row-main small{display:block;margin-top:1px;font-size:9px;color:var(--ink-3);line-height:1.5}
.seg{
  display:inline-flex;align-items:center;gap:1px;
  padding:2px;border:1px solid var(--line);border-radius:5px;
  background:var(--surface);
}
.seg button{
  display:inline-flex;align-items:center;gap:4px;
  height:23px;padding:0 8px;border-radius:3px;
  font-size:9.5px;color:var(--ink-3);white-space:nowrap;
  transition:background .12s,color .12s;
}
.seg button:hover{color:var(--ink)}
.seg button.is-active{background:var(--surface-2);color:var(--ink);font-weight:550}
.seg button .count{font-family:var(--font-mono);font-size:8px;color:var(--ink-3)}

/* toggle */
.switch{position:relative;display:inline-flex;flex:none;width:30px;height:17px;cursor:pointer}
.switch input{position:absolute;opacity:0;width:1px;height:1px}
.switch span{
  position:absolute;inset:0;border-radius:9px;
  border:1px solid var(--line);background:var(--line-2);
  transition:background .15s,border-color .15s;
}
.switch span::after{
  content:"";position:absolute;top:2px;left:2px;
  width:11px;height:11px;border-radius:50%;
  background:var(--surface);box-shadow:0 1px 1px rgba(20,27,32,.18);
  transition:transform .15s;
}
.switch input:checked + span{background:var(--prussian);border-color:var(--prussian)}
.switch input:checked + span::after{transform:translateX(13px)}
.switch input:focus-visible + span{outline:2px solid var(--prussian);outline-offset:2px}

/* ---------- tables ---------- */
.table-wrap{
  width:100%;overflow-x:auto;
  border:1px solid var(--line);border-radius:6px;
  background:var(--surface);
}
.data-table{width:100%;border-collapse:collapse;font-size:10.5px;min-width:720px}
.data-table th{
  height:34px;padding:0 11px;
  border-bottom:1px solid var(--line);
  background:var(--surface-2);
  text-align:left;font-size:8.5px;font-weight:500;color:var(--ink-3);
  letter-spacing:.02em;white-space:nowrap;
}
.data-table td{
  padding:9px 11px;
  border-bottom:1px solid var(--line-2);
  color:var(--ink-2);vertical-align:middle;
}
.data-table tbody tr:last-child td{border-bottom:0}
.data-table tbody tr:hover td{background:rgba(20,27,32,.022)}
html[data-theme="dark"] .data-table tbody tr:hover td{background:rgba(255,255,255,.025)}
.data-table .num{text-align:right;font-family:var(--font-mono);font-size:9.5px}
.data-table .actions{text-align:right;white-space:nowrap}
.data-table .actions button{margin-left:7px}
.table-foot{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  padding:8px 11px;border-top:1px solid var(--line-2);
  background:var(--surface-2);
  font-size:9px;color:var(--ink-3);
}
.table-foot .spacer{flex:1}
.pagination{display:flex;align-items:center;gap:3px}
.pagination button{
  display:grid;place-items:center;min-width:22px;height:22px;padding:0 6px;
  border:1px solid var(--line);border-radius:3px;background:var(--surface);
  font-size:9px;color:var(--ink-3);
}
.pagination button.is-active{background:var(--ink);border-color:var(--ink);color:var(--paper)}
.empty-state{
  padding:34px 18px;text-align:center;
  font-size:10.5px;color:var(--ink-3);
}

/* user cell */
.user-cell{display:flex;align-items:center;gap:8px;min-width:160px}
.avatar{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;border-radius:50%;
  background:var(--surface-2);border:1px solid var(--line);
  color:var(--ink-2);font-family:var(--font-mono);font-size:8.5px;
}
.avatar.sm{width:25px;height:25px;font-size:8px}
.avatar.admin{background:var(--ink);border-color:var(--ink);color:var(--paper)}
.user-cell-main{min-width:0}
.user-cell-main b{display:block;font-size:10.5px;font-weight:550;color:var(--ink);white-space:nowrap}
.user-cell-main span{display:block;margin-top:1px;font-size:9px;color:var(--ink-3);white-space:nowrap}
.user-cell.is-self b::after{content:"你";margin-left:4px;font-family:var(--font-sans);font-size:7.5px;color:var(--ink-3);border:1px solid var(--line);border-radius:2px;padding:0 3px}

/* ---------- roles ---------- */
.roles-layout{display:grid;grid-template-columns:268px minmax(0,1fr);gap:14px;margin-top:14px;align-items:start}
.role-panel{overflow:hidden}
.role-list{display:flex;flex-direction:column;padding:6px}
.role-item{
  display:flex;align-items:flex-start;gap:7px;width:100%;
  padding:8px;border-radius:5px;text-align:left;
  transition:background .12s;
}
.role-item:hover{background:var(--surface-2)}
.role-item.is-active{background:var(--surface-2)}
.role-item-main{flex:1;min-width:0}
.role-item-main b{display:flex;align-items:center;gap:5px;font-size:10.5px;font-weight:550;color:var(--ink-2)}
.role-item-main small{display:block;margin-top:2px;font-size:8.5px;line-height:1.4;color:var(--ink-3)}
.role-item .ic{width:12px;height:12px;color:var(--ink-3);margin-top:2px;flex:none}
.role-item.is-active .role-item-main b{color:var(--ink)}
.lock-mini{font-size:7.5px;color:var(--amber-text);border:1px solid rgba(169,116,31,.22);border-radius:2px;padding:0 3px}
.permission-panel .panel-head{align-items:flex-start}
.permission-panel .panel-head h2{font-size:13px}
.permission-panel .panel-head p{margin-top:2px;max-width:66ch}
.lock-note{
  display:inline-flex;align-items:center;gap:4px;
  font-size:8.5px;color:var(--amber-text);
  border:1px solid rgba(169,116,31,.22);border-radius:3px;padding:2px 5px;
}
.lock-note .ic{width:10px;height:10px}
.perm-table{min-width:560px}
.perm-table th{text-align:center}
.perm-table th:first-child{text-align:left}
.perm-table td{text-align:center;padding-top:7px;padding-bottom:7px}
.perm-table td:first-child{text-align:left;color:var(--ink-2)}
.perm-table .perm-group td{
  background:var(--surface-2);color:var(--ink-3);
  font-size:8.5px;font-weight:500;letter-spacing:.02em;
}
.perm-table input[type="checkbox"]{accent-color:var(--prussian);width:13px;height:13px}
.perm-table input[type="checkbox"]:disabled{opacity:.55}
.perm-table.is-locked td{color:var(--ink-3)}
.perm-note{padding:8px 14px;font-size:9px;color:var(--ink-3);background:var(--surface-2);border-top:1px solid var(--line-2)}

/* ---------- menus ---------- */
.menu-table{min-width:900px}
.menu-table td:first-child{min-width:220px}
.tree-group td{background:var(--surface-2);font-weight:550;color:var(--ink-2)}
.tree-toggle{
  display:inline-grid;place-items:center;
  width:17px;height:17px;margin-right:2px;
  border-radius:3px;color:var(--ink-3);vertical-align:-4px;
}
.tree-toggle:hover{background:var(--line-2);color:var(--ink)}
.tree-toggle .ic{width:10px;height:10px;transition:transform .15s}
.tree-toggle.is-open .ic{transform:rotate(180deg)}
.tree-pad{display:inline-block;width:18px;flex:none}
.tree-pad.x2{width:36px}
.tree-name{display:inline-flex;align-items:center;gap:5px;color:var(--ink-2)}
.tree-group .tree-name{color:var(--ink)}
.tree-name .ic{width:12px;height:12px;color:var(--ink-3)}
.menu-table .path{font-family:var(--font-mono);font-size:9px;color:var(--ink-3)}
.menu-table .perm{font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3)}
.menu-table .sort{font-family:var(--font-mono);font-size:9px;color:var(--ink-3);text-align:center}
.menu-table .visibility{font-size:9px;color:var(--ink-3)}

/* ---------- dictionaries ---------- */
.dict-layout{display:grid;grid-template-columns:286px minmax(0,1fr);gap:14px;margin-top:14px;align-items:start}
.dict-types{overflow:hidden}
.dict-search{padding:8px 10px;border-bottom:1px solid var(--line-2)}
.dict-search .search-field{width:100%;min-width:0;height:27px}
.dict-type-list{display:flex;flex-direction:column;padding:5px;max-height:560px;overflow-y:auto}
.dict-type{
  display:flex;align-items:center;gap:7px;width:100%;
  padding:8px 7px;border-radius:4px;text-align:left;
}
.dict-type:hover{background:var(--surface-2)}
.dict-type.is-active{background:var(--surface-2)}
.dict-type-main{flex:1;min-width:0}
.dict-type-main b{display:block;font-size:10.5px;font-weight:550;color:var(--ink-2)}
.dict-type-main small{display:block;margin-top:1px;font-family:var(--font-mono);font-size:8px;color:var(--ink-3)}
.dict-type .count{
  font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3);
  border:1px solid var(--line-2);border-radius:3px;padding:1px 4px;flex:none;
}
.dict-type .ic{width:10px;height:10px;color:var(--ink-3);flex:none}
.dict-head{display:flex;align-items:flex-start;gap:10px;flex-wrap:wrap;padding:12px 14px;border-bottom:1px solid var(--line-2)}
.dict-head-main{flex:1;min-width:0}
.dict-head h2{font-size:13px;font-weight:600}
.dict-head p{margin-top:2px;font-size:9.5px;color:var(--ink-3);line-height:1.5}
.dict-code{font-family:var(--font-mono);font-size:9px;color:var(--ink-3);border:1px solid var(--line-2);border-radius:3px;background:var(--surface-2);padding:2px 5px;height:19px}
.dict-toolbar{display:flex;align-items:center;gap:7px;flex-wrap:wrap;padding:8px 14px;border-bottom:1px solid var(--line-2)}
.dict-toolbar .search-field{height:27px;min-width:180px}
.dict-toolbar .spacer{flex:1}
.swatch{display:inline-block;width:11px;height:11px;border-radius:3px;flex:none;border:1px solid rgba(20,27,32,.08)}
.swatch.gray{background:#8B9499}
.swatch.blue{background:#3E6F8A}
.swatch.amber{background:#B98A3B}
.swatch.green{background:#4F7A5D}
.swatch.red{background:#A65343}
.swatch.purple{background:#6F5F86}
.color-cell{display:flex;align-items:center;gap:5px;font-size:9px;color:var(--ink-3)}
.item-status{display:flex;align-items:center;gap:6px}
.item-status .st{height:18px;font-size:8.5px}

/* ---------- audit ---------- */
.audit-table{min-width:880px}
.audit-actor{display:flex;align-items:center;gap:6px;min-width:95px}
.audit-actor .avatar{width:22px;height:22px;font-size:7.5px}
.audit-actor b{font-size:9.5px;font-weight:500;color:var(--ink-2);white-space:nowrap}
.audit-action{font-size:9.5px;color:var(--ink-2)}
.audit-resource{font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3);max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block}
.audit-ip{font-family:var(--font-mono);font-size:8.5px;color:var(--ink-3)}
.audit-json{
  margin:0;padding:10px;
  border:1px solid var(--line-2);border-radius:5px;
  background:var(--surface-2);
  font-family:var(--font-mono);font-size:8.5px;line-height:1.6;color:var(--ink-2);
  white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;
}
.audit-detail{display:flex;flex-direction:column;gap:12px}
.audit-meta{display:grid;grid-template-columns:90px minmax(0,1fr);gap:5px 10px;font-size:10px}
.audit-meta dt{color:var(--ink-3)}
.audit-meta dd{color:var(--ink-2);overflow-wrap:anywhere}
.audit-meta dd.mono{font-family:var(--font-mono);font-size:9px}

/* ---------- settings ---------- */
.settings-layout{display:grid;grid-template-columns:176px minmax(0,1fr);gap:22px;margin-top:16px;align-items:start}
.settings-nav{position:sticky;top:0;display:flex;flex-direction:column;gap:1px;padding-right:12px;border-right:1px solid var(--line-2)}
.settings-nav button{
  display:flex;align-items:center;height:30px;padding:0 9px;
  border-radius:4px;text-align:left;font-size:10px;color:var(--ink-3);
}
.settings-nav button:hover{background:var(--surface-2);color:var(--ink)}
.settings-nav button.is-active{background:var(--surface-2);color:var(--ink);font-weight:550}
.settings-form{display:flex;flex-direction:column;gap:14px;min-width:0}
.settings-section{scroll-margin-top:12px}
.settings-section .panel-head{align-items:flex-start}
.settings-section .panel-head h2{font-size:12.5px}
.settings-section .panel-head p{margin-top:2px;max-width:70ch}
.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.settings-note{
  display:flex;align-items:flex-start;gap:6px;
  padding:8px 10px;border:1px solid var(--line-2);border-radius:4px;
  background:var(--surface-2);font-size:9px;line-height:1.5;color:var(--ink-3);
}
.settings-note .ic{width:12px;height:12px;flex:none;margin-top:1px;color:var(--ink-3)}
.danger-zone{border-color:rgba(156,58,43,.28)}
.danger-zone .panel-head h2{color:var(--red)}
.danger-zone .panel-head .ic{color:var(--red)}

/* ---------- drawer ---------- */
.drawer-scrim{
  position:fixed;inset:0;z-index:80;
  background:rgba(12,18,22,.42);
  opacity:0;pointer-events:none;transition:opacity .2s;
}
.drawer-scrim.is-open{opacity:1;pointer-events:auto}
.drawer{
  position:fixed;right:0;top:0;bottom:0;z-index:90;
  display:flex;flex-direction:column;
  width:min(520px,96vw);
  background:var(--surface);
  border-left:1px solid var(--line);
  box-shadow:-24px 0 48px -32px rgba(0,0,0,.45);
  transform:translateX(102%);
  transition:transform .24s ease;
  outline:none;
}
.drawer.is-open{transform:none}
.drawer-head{
  flex:none;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;
  padding:15px 18px;border-bottom:1px solid var(--line);
}
.drawer-head h2{font-size:14px;font-weight:650;letter-spacing:-.012em}
.drawer-sub{margin-top:3px;font-size:9.5px;color:var(--ink-3);line-height:1.5}
.drawer-close{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;border:1px solid var(--line);border-radius:4px;
  background:var(--surface);color:var(--ink-2);
}
.drawer-close:hover{color:var(--ink);border-color:var(--ink-3)}
.drawer-close .ic{width:14px;height:14px}
.drawer-body{flex:1;min-height:0;overflow-y:auto;padding:16px 18px 24px}
.drawer-foot{
  flex:none;display:flex;align-items:center;gap:7px;
  padding:9px 18px;border-top:1px solid var(--line);
  background:var(--surface-2);
}
.drawer-note{
  margin-top:12px;padding:8px 10px;border:1px dashed var(--line);border-radius:4px;
  font-size:9px;line-height:1.5;color:var(--ink-3);
}
.user-summary{
  display:flex;align-items:center;gap:9px;
  padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid var(--line-2);
}
.user-summary .avatar{width:34px;height:34px;font-size:10px}
.user-summary b{display:block;font-size:12px;font-weight:600}
.user-summary span{display:block;margin-top:1px;font-size:9.5px;color:var(--ink-3)}

/* ---------- toast ---------- */
.toast{
  position:fixed;left:50%;bottom:23px;z-index:200;
  transform:translate(-50%,10px);
  display:flex;align-items:center;gap:7px;
  max-width:min(460px,calc(100vw - 32px));
  padding:8px 12px;
  border-radius:5px;
  background:var(--ink);color:var(--paper);
  font-size:10.5px;line-height:1.5;
  box-shadow:var(--shadow-lg);
  opacity:0;pointer-events:none;
  transition:opacity .18s,transform .18s;
}
.toast.is-visible{opacity:1;transform:translate(-50%,0)}
.toast .ic{width:13px;height:13px;flex:none;color:var(--amber)}
html[data-theme="dark"] .toast{background:var(--surface);color:var(--ink);border:1px solid var(--line)}

/* ---------- responsive ---------- */
@media (max-width:1180px){
  .admin-page{padding:24px 24px 56px}
  .metric-strip{grid-template-columns:repeat(3,minmax(0,1fr))}
  .metric:nth-child(3n){border-right:0}
  .grid-2{grid-template-columns:1fr}
  .roles-layout{grid-template-columns:1fr}
  .dict-layout{grid-template-columns:250px minmax(0,1fr)}
  .settings-layout{grid-template-columns:150px minmax(0,1fr);gap:16px}
  .global-search{width:200px}
}
@media (max-width:900px){
  .admin-app{grid-template-columns:1fr}
  .rail{
    position:fixed;left:0;top:0;bottom:0;width:252px;
    transform:translateX(-102%);
    transition:transform .22s ease;
    z-index:60;
  }
  .rail.is-open{transform:none}
  .rail-scrim{display:block;opacity:0;pointer-events:none;transition:opacity .2s}
  .rail-scrim.is-open{opacity:1;pointer-events:auto}
  .mobile-menu{display:grid}
  .topbar{padding:0 16px;height:54px}
  .global-search{width:170px}
  .admin-page{padding:22px 18px 48px}
  .admin-page-head{flex-direction:column;align-items:flex-start;gap:12px}
  .head-actions{width:100%}
  .settings-layout{grid-template-columns:1fr}
  .settings-nav{position:static;flex-direction:row;gap:2px;overflow-x:auto;border-right:0;border-bottom:1px solid var(--line-2);padding:0 0 6px}
  .settings-nav button{flex:none}
  .dict-layout{grid-template-columns:1fr}
  .dict-type-list{max-height:220px}
}
@media (max-width:720px){
  .topbar{gap:8px}
  .crumb span{display:none}
  .crumb .ic{display:none}
  .global-search{display:none}
  .env-chip{display:none}
  .metric-strip{grid-template-columns:repeat(2,minmax(0,1fr))}
  .metric:nth-child(2n){border-right:0}
  .metric:nth-child(3){border-top:1px solid var(--line-2)}
  .metric:nth-child(4){border-top:1px solid var(--line-2)}
  .metric:nth-child(5){border-top:1px solid var(--line-2);border-right:0}
  .form-grid,.settings-grid{grid-template-columns:1fr}
  .drawer{width:100vw}
  .toolbar{gap:6px}
  .search-field{flex:1;min-width:150px}
  .data-table{font-size:10px}
  .admin-page-head .head-actions .btn{flex:1}
  .page-title{font-size:21px}
  .panel-head{padding:8px 12px}
  .panel-body{padding:12px}
  .role-item{padding:7px}
  .toast{bottom:14px}
}
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
}
"}

