  --surface-2:#F4F3EC;
  --ink:#141B20;
  --ink-2:#4F5B63;
  --ink-3:#606B72;
  --line:#D7D5C9;
  --line-2:#E3E1D6;

  --prussian:#17465E;
  --prussian-soft:#E4ECEF;
  --amber:#A9741F;
  --amber-text:#8A5D14;
  --amber-soft:#F3E9D3;
  --red:#9C3A2B;
  --red-soft:#F6E5E0;
  --green:#3D6A4E;
  --green-soft:#E4EDE6;
