    openDrawer({ mode: 'dictType', title: '新建字典', sub: '创建一个新的枚举类型', html: html, saveText: '创建字典' });
  }

  function openDictItemDrawer(item) {
    var isEdit = !!item;
    var d = currentDictData();
    var value = item ? item.value : '';
    var html = '<div class="form-grid">' +
      '<label class="field"><span>标签</span><input class="input" id="dfItemLabel" value="' + esc(item ? item.label : '') + '" placeholder="已提交"></label>' +
      '<label class="field"><span>值</span><input class="input" id="dfItemValue" value="' + esc(value) + '" placeholder="submitted"></label>' +
      '<label class="field"><span>颜色</span><select class="select" id="dfItemColor">' + colorOptions(item ? item.color : 'gray') + '</select></label>' +
      '<label class="field"><span>排序</span><input class="input" id="dfItemSort" value="' + (item ? item.sort : 1) + '"></label>' +
      '</div>' +
      '<div class="field-row" style="margin-top:12px"><div class="field-row-main"><b>启用</b><small>停用后该值仍保留，但不再出现在可选列表中。</small></div><label class="switch"><input type="checkbox" id="dfItemEnabled"' + (!item || item.enabled ? ' checked' : '') + '><span></span></label></div>' +
      '<div class="drawer-note">当前字典：' + esc(d.name) + ' · ' + esc(d.code) + '</div>';
    openDrawer({
      mode: 'dictItem',
      target: item || null,
      title: isEdit ? '编辑字典项' : '新增字典项',
      sub: d.name + ' · ' + d.code,
      html: html,
      saveText: isEdit ? '保存字典项' : '添加字典项'
    });
  }

  function saveDictItemDrawer() {
    var label = fieldValue('dfItemLabel');
    var value = fieldValue('dfItemValue');
    if (!label || !value) {
      showToast('请填写标签和值');
      return;
    }
    var d = currentDictData();
    var payload = {
      label: label,
      value: value,
      color: fieldValue('dfItemColor') || 'gray',
      sort: Number(fieldValue('dfItemSort')) || 1,
      enabled: fieldChecked('dfItemEnabled')
    };
    if (drawerTarget) {
      Object.keys(payload).forEach(function (key) { drawerTarget[key] = payload[key]; });
      showToast('字典项已更新');
    } else {
      d.items.push(payload);
      showToast('字典项已添加');
    }
    renderDictTypes();
    renderDictItems();
    closeDrawer();
  }

  dictTypeSearch.addEventListener('input', renderDictTypes);
  dictItemSearch.addEventListener('input', renderDictItems);
  newDictBtn.addEventListener('click', openDictTypeDrawer);
  addDictItemBtn.addEventListener('click', function () { openDictItemDrawer(null); });

  dictItemRows.addEventListener('click', function (event) {
    var d = currentDictData();
    var edit = event.target.closest('[data-dict-edit]');
    if (edit) {
      var value = edit.getAttribute('data-dict-edit');
      var item = d.items.filter(function (i) { return i.value === value; })[0];
      if (item) openDictItemDrawer(item);
      return;
    }
    var toggle = event.target.closest('[data-dict-toggle]');
    if (toggle) {
      var value2 = toggle.getAttribute('data-dict-toggle');
      var item2 = d.items.filter(function (i) { return i.value === value2; })[0];
      if (item2) {
        item2.enabled = !item2.enabled;
        renderDictTypes();
        renderDictItems();
        showToast(item2.enabled ? '字典项已启用' : '字典项已停用');
      }
      return;
    }
    var del = event.target.closest('[data-dict-delete]');
    if (del) {
      var value3 = del.getAttribute('data-dict-delete');
      d.items = d.items.filter(function (i) { return i.value !== value3; });
      renderDictTypes();
      renderDictItems();
      showToast('字典项已删除');
    }
  });

  /* ============================================================
     AUDIT
     ============================================================ */
  var AUDIT = [
    { id: 'evt_9a1f', time: '今天 09:42', actor: '周丹', initials: 'ZD', category: 'menu', action: '更新菜单', actionCode: 'menu.update', resource: '/admin/menus · 管理控制台 / 菜单管理', ip: '10.0.12.4', result: 'success', detail: { path: '/admin/menus', change: 'visibility', from: 'hidden', to: 'visible' } },
    { id: 'evt_9a1e', time: '今天 09:31', actor: '周丹', initials: 'ZD', category: 'user', action: '修改用户角色', actionCode: 'user.role.update', resource: '林雨 → 运营管理员', ip: '10.0.12.4', result: 'success', detail: { user_id: 'u2', from: 'support', to: 'ops' } },
    { id: 'evt_9a1d', time: '今天 09:18', actor: '林雨', initials: 'LY', category: 'workflow', action: '发布工作流', actionCode: 'workflow.publish', resource: '客服周报 · v2', ip: '10.0.12.31', result: 'success', detail: { workflow_id: 'report', version: 'v2', steps: 7 } },
    { id: 'evt_9a1c', time: '今天 08:55', actor: '陈默', initials: 'CM', category: 'approval', action: '批准 Slack 发布', actionCode: 'approval.approve', resource: 'mcp_slack__post_message · #support-weekly', ip: '10.0.12.22', result: 'success', detail: { approval_id: 'ap_7f21', decision: 'approved', target: '#support-weekly' } },
    { id: 'evt_9a1b', time: '今天 08:31', actor: '周丹', initials: 'ZD', category: 'agent', action: '注册智能体', actionCode: 'agent.register', resource: 'code-assistant · https://code.example.com/a2a', ip: '10.0.12.4', result: 'success', detail: { slug: 'code-assistant', protocol: 'A2A 1.0', health: 'healthy' } },
    { id: 'evt_9a1a', time: '今天 08:12', actor: '系统', initials: 'SY', category: 'agent', action: '健康检查失败', actionCode: 'agent.health', resource: 'code-assistant · 502 a2a_unavailable', ip: '127.0.0.1', result: 'failure', detail: { slug: 'code-assistant', status: 502, error: 'a2a_unavailable', retry_in: '5m' } },
    { id: 'evt_9a19', time: '昨天 22:10', actor: '周丹', initials: 'ZD', category: 'dict', action: '更新字典', actionCode: 'dict.update', resource: 'task_status · 等待输入', ip: '10.0.12.4', result: 'success', detail: { dict: 'task_status', item: 'input_required', field: 'label', from: '待输入', to: '等待输入' } },
    { id: 'evt_9a18', time: '昨天 21:44', actor: '王砚', initials: 'WY', category: 'login', action: '登录失败', actionCode: 'login.failed', resource: 'wang.yan@example.com', ip: '10.0.12.55', result: 'failure', detail: { reason: 'invalid_password', attempts: 3, locked: false } },
    { id: 'evt_9a17', time: '昨天 20:15', actor: '周丹', initials: 'ZD', category: 'system', action: '更新系统设置', actionCode: 'settings.update', resource: 'A2A timeout · 30s → 60s', ip: '10.0.12.4', result: 'success', detail: { section: 'a2a', field: 'timeout_seconds', from: 30, to: 60 } },
    { id: 'evt_9a16', time: '昨天 19:02', actor: '赵可', initials: 'ZK', category: 'knowledge', action: '上传知识文档', actionCode: 'knowledge.upload', resource: '退款政策.md', ip: '10.0.12.41', result: 'success', detail: { file: '退款政策.md', chunks: 42, category: '售后' } }
