      : '<span class="st st-error"><span class="dot is-warn"></span>失败</span>';
  }

  function renderAudit() {
    var q = auditFilter.q.toLowerCase();
    var rows = AUDIT.filter(function (evt) {
      var text = (evt.actor + ' ' + evt.action + ' ' + evt.resource + ' ' + evt.ip).toLowerCase();
      var actionOk = auditFilter.action === 'all' || evt.category === auditFilter.action;
      var resultOk = auditFilter.result === 'all' || evt.result === auditFilter.result;
      return (!q || text.indexOf(q) !== -1) && actionOk && resultOk;
    });
    auditRows.innerHTML = rows.length ? rows.map(function (evt) {
      return '<tr>' +
        '<td class="mono" style="font-size:8.5px;color:var(--ink-3);white-space:nowrap">' + evt.time + '</td>' +
