        '<td><span class="audit-resource" title="' + esc(evt.resource) + '">' + esc(evt.resource) + '</span></td>' +
        '<td class="audit-ip">' + esc(evt.ip) + '</td>' +
        '<td>' + auditResultBadge(evt.result) + '</td>' +
