    if (!evt) return;
    var html = '<div class="audit-detail">' +
      '<dl class="audit-meta">' +
        '<dt>事件 ID</dt><dd class="mono">' + evt.id + '</dd>' +
        '<dt>时间</dt><dd>' + evt.time + '</dd>' +
        '<dt>操作者</dt><dd>' + esc(evt.actor) + '</dd>' +
        '<dt>操作</dt><dd>' + esc(evt.action) + ' <span class="mono">' + evt.actionCode + '</span></dd>' +
        '<dt>对象</dt><dd class="mono">' + esc(evt.resource) + '</dd>' +
        '<dt>来源 IP</dt><dd class="mono">' + evt.ip + '</dd>' +
        '<dt>结果</dt><dd>' + auditResultBadge(evt.result) + '</dd>' +
      '</dl>' +
      '<div><h3 style="font-size:11px;font-weight:600;color:var(--ink-2);margin-bottom:6px">变更内容</h3><pre class="audit-json">' + esc(JSON.stringify(evt.detail, null, 2)) + '</pre></div>' +
      '<div class="drawer-note">审计记录只读；默认保留 365 天。导出时包含完整上下文。</div>' +
    '</div>';
    openDrawer({
      mode: 'audit',
      title: '审计详情',
      sub: evt.id + ' · ' + evt.time,
      html: html,
      hideSave: true,
      cancelText: '关闭'
    });
  }

  auditSearch.addEventListener('input', function () {
    auditFilter.q = auditSearch.value;
    renderAudit();
  });
  auditAction.addEventListener('change', function () {
    auditFilter.action = auditAction.value;
    renderAudit();
  });
  auditResult.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-result]');
    if (!btn) return;
    auditFilter.result = btn.getAttribute('data-result');
    auditResult.querySelectorAll('button').forEach(function (b) {
      b.classList.toggle('is-active', b === btn);
    });
    renderAudit();
  });
  auditRows.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-audit-detail]');
    if (!btn) return;
    openAuditDetail(btn.getAttribute('data-audit-detail'));
  });
  exportAuditBtn.addEventListener('click', function () {
    showToast('审计日志已导出为 CSV（原型演示）');
  });

  /* ============================================================
     SYSTEM SETTINGS
     ============================================================ */
  var settingsNav = document.getElementById('settingsNav');
  var saveSettingsBtn = document.getElementById('saveSettingsBtn');
  settingsNav.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-scroll]');
    if (!btn) return;
    settingsNav.querySelectorAll('button').forEach(function (b) {
      b.classList.toggle('is-active', b === btn);
    });
    var target = document.getElementById(btn.getAttribute('data-scroll'));
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
  saveSettingsBtn.addEventListener('click', function () {
    showToast('系统设置已保存（原型演示）');
  });

  /* ============================================================
     DRAWER SAVE
     ============================================================ */
  drawerSave.addEventListener('click', function () {
    if (drawerMode === 'user' || drawerMode === 'invite') {
      saveUserDrawer();
      return;
    }
    if (drawerMode === 'menu') {
      if (!fieldValue('dfMenuName')) {
        showToast('请填写菜单名称');
        return;
      }
      showToast('菜单配置已保存（原型演示）');
      closeDrawer();
      return;
    }
    if (drawerMode === 'dictType') {
      var name = fieldValue('dfDictName');
      var code = fieldValue('dfDictCode');
      if (!name || !code) {
        showToast('请填写字典名称和编码');
        return;
      }
      if (DICTS.some(function (d) { return d.code === code; })) {
        showToast('字典编码已存在');
        return;
      }
      DICTS.push({ code: code, name: name, desc: fieldValue('dfDictDesc') || '自定义字典', items: [] });
      currentDict = code;
      renderDictTypes();
      renderDictItems();
      showToast('字典已创建');
      closeDrawer();
      return;
    }
    if (drawerMode === 'dictItem') {
      saveDictItemDrawer();
      return;
    }
    closeDrawer();
  });

  /* ============================================================
     DEMO / INIT
     ============================================================ */
  document.querySelectorAll('[data-demo]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      showToast(btn.getAttribute('data-demo'));
    });
  });

  renderUsers();
  renderRoles();
  renderDictTypes();
  renderDictItems();
  renderAudit();
  applyMenuVisibility();
})();
