{"content": "(function () {
  'use strict';

  var root = document.documentElement;
  var adminScroll = document.getElementById('adminScroll');
  var crumbPage = document.getElementById('crumbPage');
  var mobileMenu = document.getElementById('mobileMenu');
  var adminRail = document.getElementById('adminRail');
  var railScrim = document.getElementById('railScrim');
  var themeBtn = document.getElementById('themeBtn');
  var notifyBtn = document.getElementById('notifyBtn');
  var globalSearch = document.getElementById('globalSearch');
  var railLogout = document.getElementById('railLogout');
  var toast = document.getElementById('toast');
  var toastText = document.getElementById('toastText');

  var drawerScrim = document.getElementById('drawerScrim');
  var drawer = document.getElementById('drawer');
  var drawerTitle = document.getElementById('drawerTitle');
  var drawerSub = document.getElementById('drawerSub');
  var drawerBody = document.getElementById('drawerBody');
  var drawerSave = document.getElementById('drawerSave');
  var drawerCancel = document.getElementById('drawerCancel');
  var drawerClose = document.getElementById('drawerClose');

  var pageTitles = {
    overview: '概览',
    users: '用户管理',
    roles: '角色与权限',
    menus: '菜单管理',
    dict: '字典管理',
    audit: '审计日志',
    system: '系统设置'
  };

  var toastTimer = null;
  var drawerMode = null;
  var drawerTarget = null;

  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (ch) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch];
    });
  }

  function showToast(text) {
    toastText.textContent = text;
    toast.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toast.classList.remove('is-visible'); }, 2400);
  }

  /* ---------- theme ---------- */
  try {
    var savedTheme = localStorage.getItem('ah-admin-theme');
    if (savedTheme === 'dark' || savedTheme === 'light') root.dataset.theme = savedTheme;
  } catch (e) {}

  themeBtn.addEventListener('click', function () {
    var next = root.dataset.theme === 'dark' ? 'light' : 'dark';
    root.dataset.theme = next;
    try { localStorage.setItem('ah-admin-theme', next); } catch (e) {}
  });

  /* ---------- rail / page router ---------- */
  function openRail() {
    adminRail.classList.add('is-open');
    railScrim.classList.add('is-open');
    mobileMenu.setAttribute('aria-expanded', 'true');
  }
  function closeRail() {
    adminRail.classList.remove('is-open');
    railScrim.classList.remove('is-open');
    mobileMenu.setAttribute('aria-expanded', 'false');
  }
  mobileMenu.addEventListener('click', function () {
    if (adminRail.classList.contains('is-open')) closeRail();
    else openRail();
  });
  railScrim.addEventListener('click', closeRail);

  function showPage(name) {
    if (!pageTitles[name]) name = 'overview';
    document.querySelectorAll('.admin-page').forEach(function (page) {
      page.hidden = page.getAttribute('data-page') !== name;
    });
    document.querySelectorAll('.rail-link[data-page]').forEach(function (link) {
      var active = link.getAttribute('data-page') === name;
      link.classList.toggle('is-active', active);
      if (active) link.setAttribute('aria-current', 'page');
      else link.removeAttribute('aria-current');
    });
    crumbPage.textContent = pageTitles[name];
    document.title = pageTitles[name] + ' · Agent Hub 管理控制台';
    adminScroll.scrollTop = 0;
    try { history.replaceState(null, '', '#' + name); } catch (e) {}
    closeRail();
  }

  document.querySelectorAll('.rail-link[data-page]').forEach(function (link) {
    link.addEventListener('click', function () { showPage(link.getAttribute('data-page')); });
  });
  document.querySelectorAll('[data-page-link]').forEach(function (link) {
    link.addEventListener('click', function () { showPage(link.getAttribute('data-page-link')); });
  });
  window.addEventListener('hashchange', function () {
    var name = window.location.hash.replace('#', '');
    if (pageTitles[name]) showPage(name);
  });

  var initialHash = window.location.hash.replace('#', '');
  showPage(pageTitles[initialHash] ? initialHash : 'overview');

  /* ---------- topbar ---------- */
  globalSearch.addEventListener('keydown', function (event) {
    if (event.key !== 'Enter') return;
    var q = globalSearch.value.trim();
    if (!q) return;
    if (q.indexOf('用户') !== -1) showPage('users');
    else if (q.indexOf('审计') !== -1) showPage('audit');
    else if (q.indexOf('菜单') !== -1) showPage('menus');
    else if (q.indexOf('字典') !== -1) showPage('dict');
    else if (q.indexOf('角色') !== -1) showPage('roles');
    else showToast('跨用户、菜单和审计搜索「' + q + '」（原型演示）');
    globalSearch.value = '';
  });
  notifyBtn.addEventListener('click', function () {
    showToast('3 条待处理：1 个审批、1 个降级智能体、2 篇失败文档');
  });
  railLogout.addEventListener('click', function () {
    showToast('退出登录（原型演示）');
  });

  /* ---------- drawer ---------- */
  function openDrawer(opts) {
    drawerMode = opts.mode || null;
    drawerTarget = opts.target == null ? null : opts.target;
    drawerTitle.textContent = opts.title || '编辑';
    drawerSub.textContent = opts.sub || '';
    drawerBody.innerHTML = opts.html || '';
    drawerSave.textContent = opts.saveText || '保存';
    drawerSave.hidden = !!opts.hideSave;
    drawerCancel.textContent = opts.cancelText || '取消';
    drawerScrim.classList.add('is-open');
    drawer.classList.add('is-open');
    drawer.setAttribute('aria-hidden', 'false');
    drawerBody.scrollTop = 0;
    drawer.focus();
  }

  function closeDrawer() {
    drawerScrim.classList.remove('is-open');
    drawer.classList.remove('is-open');
    drawer.setAttribute('aria-hidden', 'true');
    drawerMode = null;
    drawerTarget = null;
  }

  drawerClose.addEventListener('click', closeDrawer);
  drawerCancel.addEventListener('click', closeDrawer);
  drawerScrim.addEventListener('click', closeDrawer);
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') closeDrawer();
  });

  function fieldValue(id) {
    var el = document.getElementById(id);
    return el ? el.value.trim() : '';
  }
  function fieldChecked(id) {
    var el = document.getElementById(id);
    return !!(el && el.checked);
  }

  /* ============================================================
     USERS
     ============================================================ */
  var USERS = [
    { id: 'u1', name: '周丹', initials: 'ZD', email: 'you@example.com', role: 'superadmin', status: 'active', last: '今天 09:42', sessions: 12, self: true },
    { id: 'u2', name: '林雨', initials: 'LY', email: 'lin.yu@example.com', role: 'ops', status: 'active', last: '今天 08:31', sessions: 8 },
    { id: 'u3', name: '陈默', initials: 'CM', email: 'chen.mo@example.com', role: 'support', status: 'active', last: '昨天 22:10', sessions: 21 },
    { id: 'u4', name: '赵可', initials: 'ZK', email: 'zhao.ke@example.com', role: 'editor', status: 'active', last: '昨天 18:02', sessions: 5 },
    { id: 'u5', name: '王砚', initials: 'WY', email: 'wang.yan@example.com', role: 'auditor', status: 'disabled', last: '10-28 11:20', sessions: 3 },
    { id: 'u6', name: '李柚', initials: 'LY', email: 'li.you@example.com', role: 'support', status: 'pending', last: '未登录', sessions: 0 }
  ];

  var ROLE_META = {
    superadmin: { label: '超级管理员', className: 'admin' },
    ops: { label: '运营管理员', className: 'ops' },
    support: { label: '客服主管', className: 'support' },
    editor: { label: '知识库编辑', className: 'editor' },
    auditor: { label: '只读审计', className: 'auditor' }
  };
  var STATUS_META = {
    active: { label: '启用', className: 'st-ok' },
    disabled: { label: '禁用', className: 'st-muted' },
    pending: { label: '待激活', className: 'st-warn' }
  };

  var userSearch = document.getElementById('userSearch');
  var userRoleFilter = document.getElementById('userRoleFilter');
  var userStatusFilter = document.getElementById('userStatusFilter');
  var userRows = document.getElementById('userRows');
  var userCount = document.getElementById('userCount');
  var userFoot = document.getElementById('userFoot');
  var inviteUserBtn = document.getElementById('inviteUserBtn');

  var userFilter = { q: '', role: 'all', status: 'all' };

  function roleLabel(key) { return ROLE_META[key] ? ROLE_META[key].label : key; }
  function statusLabel(key) { return STATUS_META[key] ? STATUS_META[key].label : key; }

  function initialsOf(name) {
    var value = String(name || '').trim();
    if (!value) return '—';
    return value.length <= 2 ? value : value.slice(0, 2);
  }

  function updateUserSummary() {
    var total = USERS.length;
    var active = USERS.filter(function (u) { return u.status === 'active'; }).length;
    var disabled = USERS.filter(function (u) { return u.status === 'disabled'; }).length;
    var pending = USERS.filter(function (u) { return u.status === 'pending'; }).length;
    var b = document.querySelectorAll('[data-page="users"] .summary-line b');
    if (b.length >= 5) {
      b[0].textContent = String(total);
      b[1].textContent = String(active);
      b[2].textContent = String(disabled);
      b[3].textContent = String(pending);
      b[4].textContent = String(Object.keys(ROLE_META).length);
    }
    var railCount = document.querySelector('.rail-link[data-page="users"] .rail-count');
    if (railCount) railCount.textContent = String(total);
  }

  function renderUsers() {
    var q = userFilter.q.toLowerCase();
    var rows = USERS.filter(function (u) {
      var text = (u.name + ' ' + u.email + ' ' + u.role).toLowerCase();
      var roleOk = userFilter.role === 'all' || u.role === userFilter.role;
      var statusOk = userFilter.status === 'all' || u.status === userFilter.status;
      return (!q || text.indexOf(q) !== -1) && roleOk && statusOk;
    });

    userRows.innerHTML = rows.length ? rows.map(function (u) {
      var role = ROLE_META[u.role];
      var status = STATUS_META[u.status];
      var avatarClass = u.role === 'superadmin' ? 'avatar admin' : 'avatar';
      return '<tr data-user-id="' + esc(u.id) + '">' +
        '<td><div class="user-cell' + (u.self ? ' is-self' : '') + '">' +
          '<span class="' + avatarClass + '">' + esc(u.initials) + '</span>' +
          '<div class="user-cell-main"><b>' + esc(u.name) + '</b><span>' + esc(u.email) + '</span></div>' +
        '</div></td>' +
        '<td><span class="role-badge ' + role.className + '">' + role.label + '</span></td>' +
        '<td><span class="st ' + status.className + '">' + status.label + '</span></td>' +
        '<td class="mono" style="font-size:9px;color:var(--ink-3)">' + esc(u.last) + '</td>' +
        '<td class="num">' + u.sessions + '</td>' +
        '<td class="actions"><button class="text-link" data-edit-user="' + esc(u.id) + '">编辑</button></td>' +
      '</tr>';
    }).join('') : '<tr><td colspan="6"><div class="empty-state">没有匹配的用户。调整搜索或筛选后重试。</div></td></tr>';

    userCount.textContent = rows.length + ' / ' + USERS.length;
    userFoot.textContent = '显示 ' + rows.length + ' 个用户 · 共 ' + USERS.length + ' 个';
    updateUserSummary();
  }

  function userRoleOptions(selected) {
    return Object.keys(ROLE_META).map(function (key) {
      return '<option value="' + key + '"' + (key === selected ? ' selected' : '') + '>' + ROLE_META[key].label + '</option>';
    }).join('');
  }
  function userStatusOptions(selected) {
    return Object.keys(STATUS_META).map(function (key) {
      return '<option value="' + key + '"' + (key === selected ? ' selected' : '') + '>' + STATUS_META[key].label + '</option>';
    }).join('');
  }

  function openUserDrawer(user, mode) {
    var isInvite = mode === 'invite';
    var role = user ? user.role : 'support';
    var status = user ? user.status : 'pending';
    var html = '<div class="form-grid">' +
      '<label class="field"><span>姓名</span><input class="input" id="dfName" value="' + esc(user ? user.name : '') + '" placeholder="成员姓名"></label>' +
      '<label class="field"><span>邮箱</span><input class="input" id="dfEmail" type="email" value="' + esc(user ? user.email : '') + '" placeholder="name@example.com"></label>' +
      '<label class="field"><span>角色</span><select class="select" id="dfRole">' + userRoleOptions(role) + '</select></label>' +
      (isInvite
        ? '<label class="field"><span>状态</span><input class="input" value="待激活" disabled></label>'
        : '<label class="field"><span>状态</span><select class="select" id="dfStatus">' + userStatusOptions(status) + '</select></label>') +
      '</div>' +
      (isInvite
        ? '<div class="drawer-note">邀请邮件会发送到该邮箱。账号在首次登录后激活，并继承所选角色的菜单权限。</div>'
        : '<div class="drawer-note">修改角色会同步更新该用户的菜单与操作权限；禁用后该用户会被立即移出在线会话。</div>');

    openDrawer({
      mode: isInvite ? 'invite' : 'user',
      target: user || null,
      title: isInvite ? '邀请用户' : '编辑用户',
      sub: isInvite ? '通过邮箱邀请成员加入 Agent Hub' : (user.id + ' · ' + user.email),
      html: html,
      saveText: isInvite ? '发送邀请' : '保存用户'
    });
  }

  function saveUserDrawer() {
    var name = fieldValue('dfName');
    var email = fieldValue('dfEmail');
    var role = fieldValue('dfRole') || 'support';
    if (!name || !email) {
      showToast('请填写姓名和邮箱');
      return;
    }
    if (drawerMode === 'invite') {
      USERS.push({
        id: 'u' + Date.now(), name: name, initials: initialsOf(name), email: email,
        role: role, status: 'pending', last: '未登录', sessions: 0
      });
      showToast('邀请已发送给 ' + email);
    } else if (drawerMode === 'user' && drawerTarget) {
      drawerTarget.name = name;
      drawerTarget.initials = drawerTarget.self ? drawerTarget.initials : initialsOf(name);
      drawerTarget.email = email;
      drawerTarget.role = role;
      drawerTarget.status = fieldValue('dfStatus') || drawerTarget.status;
      showToast('用户已更新');
    }
    renderUsers();
    renderRoles();
    closeDrawer();
  }

  userSearch.addEventListener('input', function () {
    userFilter.q = userSearch.value;
    renderUsers();
  });
  userRoleFilter.addEventListener('change', function () {
    userFilter.role = userRoleFilter.value;
    renderUsers();
  });
  userStatusFilter.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-status]');
    if (!btn) return;
    userFilter.status = btn.getAttribute('data-status');
    userStatusFilter.querySelectorAll('button').forEach(function (b) {
      b.classList.toggle('is-active', b === btn);
    });
    renderUsers();
  });
  userRows.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-edit-user]');
    if (!btn) return;
    var id = btn.getAttribute('data-edit-user');
    var user = USERS.filter(function (u) { return u.id === id; })[0];
    if (user) openUserDrawer(user, 'user');
  });
  inviteUserBtn.addEventListener('click', function () { openUserDrawer(null, 'invite'); });
  document.querySelectorAll('[data-open-invite]').forEach(function (btn) {
    btn.addEventListener('click', function () { openUserDrawer(null, 'invite'); });
  });

  /* ============================================================
     ROLES
     ============================================================ */
  var ROLES = [
    { key: 'superadmin', name: '超级管理员', desc: '拥有全部菜单与操作权限，系统内置。', builtin: true },
    { key: 'ops', name: '运营管理员', desc: '管理工作流、智能体、任务和知识库；可查看用户与审计。', builtin: false },
    { key: 'support', name: '客服主管', desc: '使用工作台、处理审批与任务；不可进入管理控制台。', builtin: false },
    { key: 'editor', name: '知识库编辑', desc: '维护知识库与工作流，不参与用户管理。', builtin: false },
    { key: 'auditor', name: '只读审计', desc: '只读访问审计日志与用户列表。', builtin: false }
  ];

  var PERMISSIONS = [
    { group: '工作台', rows: [
      { label: '对话', view: 'chat:read', write: 'chat:write' },
      { label: '工作流', view: 'workflow:read', write: 'workflow:write' },
      { label: '智能体', view: 'agent:read', write: 'agent:write' },
      { label: '任务', view: 'task:read', write: 'task:write' },
      { label: '知识库', view: 'knowledge:read', write: 'knowledge:write' }
    ]},
    { group: '管理控制台', rows: [
      { label: '概览', view: 'overview:read', write: '' },
      { label: '用户管理', view: 'user:read', write: 'user:write' },
      { label: '角色与权限', view: 'role:read', write: 'role:write' },
      { label: '菜单管理', view: 'menu:read', write: 'menu:write' },
      { label: '字典管理', view: 'dict:read', write: 'dict:write' },
      { label: '审计日志', view: 'audit:read', write: '' },
      { label: '系统设置', view: 'system:read', write: 'system:write' }
    ]},
    { group: '操作权限', rows: [
      { label: '发布工作流', view: '', write: 'workflow:publish' },
      { label: '注册智能体', view: '', write: 'agent:register' },
      { label: '删除知识文档', view: '', write: 'knowledge:delete' },
      { label: '审批决定', view: '', write: 'approval:decide' }
    ]}
  ];

  var ALL_PERMS = [];
  PERMISSIONS.forEach(function (group) {
    group.rows.forEach(function (row) {
      if (row.view) ALL_PERMS.push(row.view);
      if (row.write) ALL_PERMS.push(row.write);
    });
  });

  var ROLE_PERMS = {
